        }
        // Avoid opening bins for items that fit the mean residual well.
        if fitting_bins_count >= 1 && mean_residual >= item_f
            && (mean_residual - item_f) < 0.10 * cap {
            score += 90.0 * (1.0 - (mean_residual - item_f) / (0.10 * cap));
        }
        // Late stream — strongly discourage any new bin.
        if progress > 0.75 {
            score += 60.0 * progress;
        }
        // Early stream with few bins — allow fresh bins for big items.
        if progress < 0.3 && item_ratio > 0.5 && open_bins_count < 3 {
            score -= 55.0 * item_ratio;
        }
        // Lookahead closure in an existing bin.
        if fitting_bins_count >= 1 && next_item_size > 0
            && (bin_residual).saturating_sub(item_size) == next_item_size {
            score += 140.0;
        }
        // Fresh residual can host the next item.
        if next_item_size > 0 && next_item_size as f64 > cap - item_f {
            score -= 35.0;
        }
        // Several fitting bins with large mean residual: discourage new bins.
        if fitting_bins_count >= 2 && mean_residual > 0.45 * cap {
            score += 40.0 * (mean_residual / cap - 0.45);
        }
        // Chain seeding: fresh residual exactly matches next item.
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 45.0;
        }
    }

    // Reward exact closure of an existing bin.
    if post_residual == 0 && bin_residual != bin_capacity && fitting_bins_count >= 1 {
        score -= 60.0 * (1.0 - item_ratio);
    }

    // Endgame consolidation.
    if progress > 0.9 && pr > 0.0 {
        score -= 30.0 * (1.0 - pr / cap) * progress;
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect fit: close the bin decisively.
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual < 10 {
        // Tiny dead space is nearly useless.
        score += 70.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Two-step lookahead: exact match with next item means the bin closes next step.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 700.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 250.0 * (1.0 - gap / cap);
        } else {
            // Dead space too small for the next item.
            let dead = post_residual as f64;
            score += 0.45 * dead;
            score += 45.0 * (1.0 - dead / next);
        }
    }

    // Tight-packing bias: prefer bins whose residual is below the mean.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.1 * (mean_residual - post_residual as f64).max(0.0);

    // Open-bin pressure: discourage bin proliferation, stronger late in stream.
    score += 2.5 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 220.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 120.0 + 180.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
        if item_size as f64 > 0.6 * cap {
            score -= 45.0;
        }
        if open_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild preference for consuming large items' space efficiently.
    score -= 0.05 * item_size as f64;

    score
}

