        }
        if next_item_size > 0 && next_item_size as f64 > 0.7 * cap && fitting_bins_count == 0 {
            score -= 60.0;
        }
        if mean_residual > 0.35 * cap && item_ratio < 0.5 {
            score += 55.0 * (mean_residual / cap - 0.35).min(0.4);
        }
        if progress < 0.2 && open_bins_count < 4 {
            score += 25.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual > 0.5 * cap {
            score += 45.0 * ((mean_residual / cap - 0.5) * 2.0).min(1.0);
        }
        // Never open a new bin when an existing bin would close exactly.
        if post_residual == 0 && fitting_bins_count >= 1 {
            score += 400.0;
        }
        // Never open a new bin when the item nearly fills some existing bin
        // (slivers are the dominant waste mode).
        if fitting_bins_count >= 1 && pr > 0.0 && pr < 0.12 * cap {
            score += 120.0 * (1.0 - pr / (0.12 * cap));
        }
        // Forbid new bins when a perfect closure exists late in stream.
        if post_residual == 0 && progress > 0.7 {
            score += 150.0 * progress;
        }
        // Resist opening new bins when existing residuals can host next item too.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let next = next_item_size as f64;
            if pr >= next {
                score += 45.0 * progress;
            }
        }
        // Resist new bins when some existing residual can host BOTH current
        // and next item (combined lookahead compaction).
        if next_item_size > 0 && fitting_bins_count >= 1 && (item_f + next_item_size as f64) <= cap {
            score += 30.0 * (1.0 - (item_f + next_item_size as f64) / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress * progress;
    let coupling = norm_pr * (1.0 + 2.0 * p) * (1.0 + 0.5 * progress * norm_pr);

    let mut score = pr + 6.0 * coupling;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= 8.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize when this bin is one of many fitting candidates (prefer scarcity)
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0) as f64;
    } else {
        score -= 5.0; // last-chance bin: strongly favor using it
    }

    // Lookahead: penalize leaving residual that neither fits nor helps next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 4.0 * (1.0 - progress) * (nxt / cap);
        } else {
            score += 6.0 * (1.0 - nxt / cap) * (1.0 - norm_pr);
        }
    }

    // Mild penalty relative to mean residual to prefer bins below-average fullness
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: keep neutral baseline, slightly favored early, penalized late
    if bin_residual == bin_capacity {
        score = 30.0 - 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item are "dead space" -> heavy penalty.
    let dead_threshold: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= tightness * 10.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover -> dead space for the lookahead.
        score += (post_residual as f64) * 0.5;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, reduced when open-bin pressure is high
        // or mean residual across open bins is already large (poor spread).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_cost = 30.0 + open_bins_count as f64 * -0.5 + mean_residual * 0.2 - progress * 5.0;
        score = open_cost + (bin_capacity - item_size) as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score = post_residual as f64 * (1.0 + 0.35 * fit_ratio);

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small dead zones are reusable for
    // tiny items (1..=10); mid zones (11..=30) risk becoming dead space.
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        score -= 8.0; // reusable micro-residual class
    } else if pr > 10 && pr <= 30 {
        score += 12.0; // awkward class: too small for most items
    } else if pr > 30 && pr <= 50 {
        score -= 3.0; // still broadly useful
    }

    // Integer-division thresholds: residual divisible by common item sizes
    // is more likely to be exactly consumed later.
    if pr >= 10 && (pr % 10 == 0) {
        score -= 4.0;
    }
    if pr >= 25 && (pr % 25 == 0) {
        score -= 2.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0 + (next_item_size as f64 / pr.max(1) as f64) * 8.0;
        } else {
            score += 6.0; // this bin becomes dead for the next item
            // penalize more if residual lands in awkward class
            if pr > 0 && pr < next_item_size && pr < 20 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly
    // (item leaves large residual or no bin fits well).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        // Default modest score: an empty bin has residual 100.
        score = 100.0 - 0.5 * pressure;
        if fitting_bins_count == 0 {
            score -= 60.0; // forced new bin
        } else {
            // discourage opening new bin when a decent fit exists
            let best_possible = (bin_capacity - item_size) as f64;
            if best_possible < 20.0 {
                score += 40.0;
            }
            if next_item_size > 0 && next_item_size > item_size && next_item_size > mean_residual {
                score -= 20.0; // next item is big; keep open bins flexible anyway
                score += 10.0;
            }
        }
        // Early in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Mild preference to fill bins with larger mean residual (balance load).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    score
}

