        // Base cost of opening a new bin, reduced when open-bin pressure is high
        // or mean residual across open bins is already large (poor spread).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_cost = 30.0 + open_bins_count as f64 * -0.5 + mean_residual * 0.2 - progress * 5.0;
        score = open_cost + (bin_capacity - item_size) as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit: bin is closed exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward post_residual that exactly matches
    // the next item size (this bin becomes perfectly filled in two steps).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // Next item fits here too; the closer the match, the better.
            let gap = (post_residual - next_item_size) as f64;
            score -= 300.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item will NOT fit in the residual: penalize dead space
            // that is too small for the upcoming item.
            let dead = post_residual as f64;
            score += 0.5 * dead;
            // Extra penalty if dead space is small but useless for next item.
            if dead < next_item_size as f64 && dead > 0.0 {
                score += 50.0 * (1.0 - dead / next_item_size as f64);
            }
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer bins whose remaining space is already small (tight packing).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.1 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin is attractive only if it yields
    // a much better long-term structure. Penalize it mildly so open bins with
    // good fits win, but keep it viable when open bins leave bad residuals.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses
        // (early on, opening bins builds a healthy pool of residuals).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 120.0 + 180.0 * progress;

        // Reward opening a fresh bin when the current item leaves a residual
        // that matches the next item well (fresh capacity is flexible).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
        // If no open bin fits well (many fitting bins but all tight), new bin
        // becomes more appealing when item is large relative to capacity.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 40.0;
        }
    }

    // Slight preference for filling bins with larger residuals when item is small.
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fills: residual <= 10 is essentially dead space anyway.
    if post_residual <= 10 {
        score -= 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual < 20 {
        // Penalize residuals too small for the minimum item (unusable dead space).
        score += (20 - post_residual) as f64 * 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: reward residuals that can host the next item after this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect pairing: next item exactly consumes what's left.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.5;
        } else {
            // Penalize leftovers the next item cannot use, scaled by how close we are to full.
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    } else {
        // End of stream: residual value drops, just fill anything.
        score -= 20.0;
    }

    // Global pressure: when many bins are open, consolidate; when few, prefer spreading.
    if open_bins_count > 3 {
        score -= (open_bins_count as f64).ln() * 4.0;
    } else {
        score += (4 - open_bins_count.min(4)) as f64 * 2.0;
    }

    // Mean-residual coupling: prefer bins below the mean residual (denser bins) when mean is high.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > 30.0 {
        let denser = (mean_residual - bin_residual as f64).max(0.0);
        score -= denser * 0.25 * (0.5 + progress);
    }

    // Time horizon: early on, keep bins flexible (favor large post_residual slightly);
    // late in the stream, aggressively close out bins.
    score += post_residual as f64 * (0.6 - progress) * 0.5;
    score -= progress * 15.0;

    // New-bin candidate: only attractive when nothing fits well or the stream is young.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 80.0 } else { 0.0 };
        score = 70.0 + (1.0 - progress) * 30.0 - desperation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fits (penalize large residuals); later, tolerate them.
    let progress_weight = 0.5 * (1.0 - progress);
    score += progress_weight * cap * norm_pr * norm_pr * (1.0 + norm_item);

    // Reward near-perfect packing with a smooth cubic bonus on small residuals.
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item (smooth interaction).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (ni - pr).max(0.0) / cap;
        score += 25.0 * gap * gap * (1.0 - progress);
        // Reward leaving exactly enough room for the next item (smooth kernel).
        let fit_kernel = (-((pr - ni) / cap).powi(2) * 40.0).exp();
        score -= 20.0 * fit_kernel;
    }

    // Last-chance bin: strongly favor using it (smooth exponential reward).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 * (1.0 + norm_item);
    }

    // Mild penalty for scattering across many open bins, smoothed by progress.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Encourage bins whose residual is close to the mean (balanced packing).
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: make it slightly unattractive unless residuals are all poor.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: reward residuals that are
    // "usable" by common item sizes via modulo/integer-division structure ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement
    let frac = pr / cap;

    // Class A: post_residual is an exact multiple of small harmonic steps
    // (10, 20, 25, 50) => residual is likely reusable by future items.
    let harmonic_bonus = if post_residual == 0 {
        -60.0 // perfect fit, best possible outcome
    } else if post_residual % 50 == 0 {
        -25.0
    } else if post_residual % 25 == 0 {
        -15.0
    } else if post_residual % 20 == 0 {
        -12.0
    } else if post_residual % 10 == 0 {
        -8.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Class B: integer-division threshold — small dead zones (< 10) are dead
    // space, penalize them quadratically.
    if post_residual < 10 && post_residual > 0 {
        score += 12.0 + (10.0 - pr) * 2.0;
    }

    // Class C: lookahead coupling — does next_item_size fit exactly or
    // harmonically into post_residual?
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0; // next item fills this bin perfectly
        } else if next_item_size < post_residual {
            let rem = post_residual - next_item_size;
            // harmonic remainder after the lookahead item
            if rem == 0 {
                score -= 35.0;
            } else if rem % 10 == 0 {
                score -= 10.0;
            } else if rem < 10 {
                score += 8.0; // creates dead space after lookahead
            }
        } else {
            // next item cannot use this residual: residual likely wasted
            score += 5.0 + (n - pr).min(30.0) * 0.3;
        }
    }

    // Class D: capacity-fraction thresholds
    if frac <= 0.05 {
        score -= 20.0; // nearly full bin, excellent
    } else if frac >= 0.5 {
        // bin still more than half empty after placement: fine for big
        // residual but penalize if item was small (poor packing density)
        if (item_size as f64) < 0.3 * cap {
            score += 6.0;
        }
    }

    // Class E: last-chance bin — if this is the only fitting bin, strongly
    // favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (residual equals capacity). Give it a mild baseline penalty so we
    // prefer filling existing bins unless they create dead space.
    if bin_residual == bin_capacity {
        score += 14.0 + mean_residual * 0.15;
        // late in the stream, avoid spawning bins unnecessarily
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Slight preference to spread load when many bins are open and mean
    // residual is high (avoid extreme fragmentation in one bin).
    if open_bins_count > 3 && (bin_residual as f64) > mean_residual * 1.5 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for the smallest plausible item) are heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item.max(next_item_size.min(50)) {
        score += 60.0; // dead space penalty
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Tight fit reward: fraction of bin used
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= 40.0 * fill * fill;
    }

    // Penalize leaving gaps that cannot fit the lookahead item if the
    // current bin could otherwise have hosted it later.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward reserving space exactly for the lookahead item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual - item_size as f64;
        score = 10.0 + open_bins_count as f64 * 2.0;
        if avg_fit < 0.0 {
            score -= 20.0; // nothing fits anywhere: open new bin
        }
    } else {
        // Mild preference for bins below mean residual (consolidate fuller bins)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: residual after placement exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits within post_residual (chainable bin): reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - tightness / bin_capacity as f64);
    }

    // Penalize dead space smaller than the smallest plausible next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0 + 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: bins tighter than average are more valuable.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: mild penalty so it's only chosen when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, prefer closing out existing bins over opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight reward for high fill ratio.
    score -= 0.1 * (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.5 * fit_ratio * (bin_residual as f64);

    // Penalize large dead space quadratically (unusable gaps).
    if post_residual > 0 {
        score += 0.02 * (post_residual as f64).powi(2);
    }

    // Perfect or near-perfect fit gets a big bonus.
    if post_residual < 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Lookahead: reward if the next item can fit into the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chain two items in this bin.
            let chain_waste = post_residual - next_item_size;
            score -= 6.0 - 0.1 * chain_waste as f64;
        } else {
            // Next item won't fit here; mild penalty proportional to leftover.
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins have poor fits and many open bins already exist.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin grows with stream progress (toward the end,
        // prefer filling existing bins).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + 30.0 * progress + 2.0 * open_bins_count as f64;

        // If no open bin fits well (fitting bins exist but all loose), allow new bin.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += 0.3 * mean_residual;
    }

    // Slight preference for bins whose residual deviates below mean (more filled).
    score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    // Early stream: encourage consolidating into few bins.
    if open_bins_count > 3 {
        score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to progress
    let mut score = pr;

    // Squared dead-space penalty, amplified as stream progresses
    let sq = norm_pr * norm_pr;
    score += cap * sq * (0.5 + 1.5 * progress);

    // Cubic coupling: heavily penalize mid-range residuals (awkward gaps) late in stream
    let cube = sq * norm_pr;
    score += cap * 2.0 * cube * progress * (1.0 - progress) * 4.0;

    // Reward tight fits: subtract for small post_residual relative to capacity
    score -= cap * (1.0 - norm_pr) * (1.0 - norm_pr) * 0.3;

    // Lookahead coupling: penalize if next item cannot use post_residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns > pr {
            score += 8.0 * (ns - pr) / cap * (1.0 + progress);
        } else {
            // next item fits: reward residual close to next item size
            score -= 6.0 * (1.0 - (pr - ns).abs() / cap);
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mean residual coupling: prefer bins below mean residual (larger gaps used first)
    score += 0.5 * (mean_residual - pr);

    // Slight preference for consolidating into fewer bins as open bins grow
    score += 0.3 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 25 (quarter-capacity)
    // are "harmonic" slots that future items (1..100) are most likely to reuse.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Reward residuals that are harmonic classes (multiples of 25 or exactly 50).
    if post_residual % quarter == 0 {
        score -= 6.0;
    }
    if post_residual == half {
        score -= 3.0;
    }

    // Penalize dead-space classes: small non-zero residuals (1..=10) are nearly unusable.
    if post_residual > 0 && post_residual <= 10 {
        score += 12.0;
    }

    // Integer-division threshold: if post_residual can exactly fit the next item, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic match: post_residual is an exact multiple class of next item.
            if post_residual % next_item_size == 0 {
                score -= 8.0;
            } else {
                score -= 4.0;
            }
        } else {
            // Next item cannot fit here; penalize proportionally to wasted potential.
            score += 5.0 + (next_item_size - post_residual) as f64 * 0.1;
        }

        // Modulo coupling: if item + next_item sums to a harmonic class (50 or 100),
        // placing here is especially valuable.
        let pair_sum = item_size + next_item_size;
        if pair_sum == bin_capacity {
            score -= 10.0;
        } else if pair_sum == half {
            score -= 5.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when good fitting bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score += waste * (0.6 + 0.4 * progress);
        // New bins are more acceptable late in the stream or when open bins are crowded.
        if mean_residual < item_size as f64 {
            score -= 8.0;
        }
        if open_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mild penalty for deviating far from the mean residual (keeps bin classes balanced).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100 range),
    // and increasingly wasteful the smaller it is.
    if post_residual > 0 {
        // Gap smaller than 10 cannot hold anything (min item size 10 per classic range),
        // but with unknown distribution use graded penalty.
        if post_residual < 10 {
            score += 1000.0; // absolute dead space
        } else if post_residual < 20 {
            score += 200.0;
        } else if post_residual < 35 {
            score += 40.0;
        } else if post_residual < 50 {
            score += 8.0;
        }
        // Non-linear coupling: the tighter the fit, the better — reward exactness.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 15.0 * tightness * tightness;
    } else {
        // Perfect fill: strong reward.
        score -= 500.0;
    }

    // Dead space relative to next item: if the post-residual cannot host the next item,
    // and no other bin likely can either, this gap is wasted potential.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0;
    }
    // If post-residual exactly accommodates the lookahead item, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity as u32 {
        score -= 60.0;
    }

    // Open-bin pressure: penalize placements that leave many half-empty bins around.
    // Encourage consolidating into fewer bins when open_bins_count is high.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * (0.5 + 0.5 * progress) * 2.0;

    // Prefer bins whose residual is above the mean (fill the emptier bins first),
    // keeping tighter bins reserved for small items.
    if (bin_residual as f64) > mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // New-bin candidate: opening a new bin is expensive; only attractive when
    // the item is large relative to capacity (few future fit options) or all
    // existing fits would create dead space.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Base cost of a fresh bin.
        score += 150.0;
        // Large items justify a new bin.
        score -= 220.0 * large_item * large_item;
        // If no open bin is a decent fit (this call is the fallback), the new bin
        // competes fairly: reduce its penalty when fits are scarce.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, avoid proliferating bins for small leftovers.
        if progress > 0.7 && item_size < 30 {
            score += 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: zero dead space is ideal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how snugly it fills the remainder.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack_after_next / bin_capacity as f64);
            // Bonus if the pair leaves a perfectly reusable small residual (0 or tiny).
            if slack_after_next == 0.0 {
                score -= 100.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize wasted potential.
            score += 60.0;
        }
    }

    // Compare post_residual against mean residual across open bins.
    // Leaving this bin far below mean residual creates fragmented dead space.
    let deviation = mean_residual - post_residual as f64;
    if deviation > 0.0 {
        // Post-residual below mean: this bin becomes an outlier small hole -> penalize mildly.
        score += 0.5 * deviation;
    } else {
        // Post-residual above mean: keeps bin flexible -> small reward.
        score += 0.2 * deviation;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large and current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty for opening a new bin.
        score += 120.0;
        // Late in the stream with few fitting bins, new bin may be reasonable.
        if fitting_bins_count <= 1 {
            score -= 180.0 * progress;
        }
        // Large items pack better in fresh bins.
        if item_size > bin_capacity / 2 {
            score -= 80.0;
        }
    }

    // Prefer tighter bins generally: small residual before placement is a good match.
    score += 0.3 * (bin_residual as f64 - item_size as f64);

    // Mild preference for using existing bins as stream progresses.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fits aggressively.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tight * tight;

    // Exact fit is a jackpot.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Penalize tiny dead space that nothing small can use later
    // (residual below the minimum item size is pure waste).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = (next_item_size as f64) / (bin_capacity as f64);
        score -= 18.0 * chain + 8.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here regardless; mild penalty for stranding space.
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    // rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins with slack -> consolidate;
    // few open bins -> new bins are cheap, so explore.
    let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate score.
        score += 15.0 + 0.5 * (open_bins_count as f64);
        if pressure > 4.0 {
            score -= 20.0; // too many open bins with slack: don't add more
        }
        // Late in the stream, avoid opening bins for small items.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.8 && item_size < 40 {
            score += 30.0 * progress;
        }
    } else {
        // Prefer bins with below-average residual (avoid splitting big gaps).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // Mild preference for filling bins that are already more than half full.
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: post residual, mildly non-linear (dead space penalized super-linearly)
    let mut score = pr as f64 + 40.0 * norm_pr * norm_pr;

    // Smooth progress coupling: late in stream, tighter packing preferred
    let progress_weight = 0.5 + 0.5 * progress;
    score -= progress_weight * 30.0 * fit_ratio * (1.0 - norm_pr);

    // Last-chance bonus (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            score -= 15.0 * (1.0 - (nxt / pr.max(1.0) - 1.0).abs().min(1.0));
        } else {
            score += 8.0 * (nxt - pr as f64) / cap;
        }
    }

    // Penalize bins far from mean residual (fragmentation of residual distribution)
    score += 5.0 * ((pr - mean_residual) / cap).abs();

    // Slight penalty for too many open bins late in stream
    score += 0.5 * open_bins_count as f64 * progress;

    // Favor high fill ratio with smooth cubic term
    score -= 20.0 * fit_ratio * fit_ratio * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: exact residue classes modulo capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit -> strong reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space classes: residuals that very few future items can use
        // Items in [1,100]; small residuals (<10) are nearly dead space.
        if post_residual < 10 {
            score += 60.0;
        }
        // Modulo classes on post_residual: residuals congruent to values
        // reachable by typical item sizes get a mild bonus.
        let m5 = post_residual % 5;
        let m10 = post_residual % 10;
        if m5 == 0 {
            score -= 8.0; // round residuals are easier to fill
        }
        if m10 == 0 && post_residual >= 20 {
            score -= 6.0;
        }
        // Integer-division threshold: how many "average" items fit in the leftover
        let avg_item = 55.0f64; // mid-range item size guess
        let fits = (pr / avg_item).floor();
        score -= fits * 12.0;

        // Fractional capacity coupling: post_residual relative to capacity
        let frac = pr / cap;
        if frac < 0.15 {
            score += 25.0 * (0.15 - frac); // penalize tiny slivers
        } else if frac > 0.6 {
            score -= 10.0 * (frac - 0.6); // reward leaving large usable space
        }

        // Lookahead harmonic: does next_item_size divide/match the post_residual class?
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 400.0; // perfect chain
            } else if next_item_size <= post_residual {
                let gap = post_residual - next_item_size;
                score -= 30.0;
                if gap % 10 == 0 {
                    score -= 15.0; // harmonic gap
                }
                if gap < 10 {
                    score += 20.0; // would create sliver after next item
                }
            } else {
                score += 15.0; // next item can't use this bin's leftover
            }
        }

        // Last-chance bin: strongly prefer using it to avoid opening a new bin
        if fitting_bins_count == 1 {
            score -= 90.0;
        } else if fitting_bins_count > 2 {
            score += 4.0 * (fitting_bins_count as f64 - 2.0);
        }

        // Mean residual coupling: prefer bins near the mean (balanced packing)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.3;

        // Early stream: keep bins tight; late stream: consolidate
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 10.0;

        // New-bin candidate: only attractive when nothing fits well
        if bin_residual == bin_capacity {
            let good_open_exists = fitting_bins_count > 0 && pr >= 0.0;
            // base new-bin cost
            score += 120.0;
            if next_item_size > 0 && next_item_size as f64 > mean_residual {
                score -= 40.0; // fresh bin useful for large next item
            }
            if open_bins_count == 0 {
                score -= 200.0; // must open a bin
            }
            let _ = good_open_exists;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: bin closes exactly. Strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Two-step lookahead: reward residuals that match the next item exactly
    // or closely (bin can absorb the next item too).
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 300.0 * (1.0 - gap / cap_f);
            // NEW: extra bonus when post_residual can host next item AND still
            // leave a residual matching a small follow-up (soft 3-step chain).
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= cap_f as u32 / 4 {
                score -= 40.0 * (1.0 - after_next as f64 / (cap_f / 4.0));
            }
        } else {
            // Dead space too small for the next item: penalize proportionally
            // to how close-but-unusable it is.
            let dead = post_residual as f64;
            score += 0.5 * dead;
            if dead > 0.0 {
                score += 50.0 * (1.0 - dead / next_f);
            }
        }
    }

    // Tight-packing pressure relative to mean residual across open bins.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.1 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly prefer using the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // NEW: when several bins fit, discourage using a bin whose post_residual
    // is very small but nonzero (fragment sliver that nothing else can use),
    // unless it is a perfect fit (already handled above).
    if post_residual > 0 && post_residual < item_size.min(next_item_size) && fitting_bins_count > 1 {
        score += 25.0;
    }

    // NEW: when the item nearly fills the bin (residual <= 10% of capacity),
    // reward committing to it regardless of lookahead — near-closures are rare
    // opportunities and slivers waste capacity.
    if post_residual > 0 && post_residual as f64 <= 0.1 * cap_f {
        score -= 60.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of opening a new bin grows with stream progress and with
        // the number of open bins (avoid bin pool sprawl late in the stream).
        score += 120.0 + 180.0 * progress + 4.0 * open_bins_count as f64;

        // Fresh capacity is flexible when post_residual can host next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
        // Large items relative to capacity favor a fresh bin.
        if item_size as f64 > 0.6 * cap_f {
            score -= 40.0;
        }
        // NEW: if no open bin leaves a residual that can host the next item,
        // opening a fresh bin preserves future flexibility.
        if next_item_size > 0 && fitting_bins_count > 0 && post_residual < next_item_size {
            score -= 30.0;
        }
    }

    // Slight preference for filling bins with larger items.
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
