        }
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Prefer bins with larger residuals (keep flexible bins busy).
    score -= 0.08 * (bin_residual as f64 - mean_residual);

    // Mild bias toward placing small items into already-tight bins.
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
