    // Dead-space avoidance with graded penalties.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 400.0;
        } else if post_residual < 20 {
            score += 120.0;
        } else if post_residual < 35 {
            score += 30.0;
        } else if post_residual < 50 {
            score += 6.0;
        }
        let tightness = 1.0 - (post_residual as f64 / cap);
        score -= 15.0 * tightness * tightness;
        // Quartic dead-space penalty in the awkward zone.
        if pr < 0.25 * cap {
            let r = pr / cap;
            score += 140.0 * r * (1.0 - 4.0 * r) * (1.0 - r) + 25.0 * r * r;
        }
    }

    // Two-step lookahead with chain anticipation.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 950.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 360.0 * (1.0 - gap / cap);
            if nxt > 0.5 * cap && fitting_bins_count <= 2 {
                score -= 150.0 * (nxt / cap);
