            if pr - nxt >= item_f {
                score -= 40.0 * item_ratio;
            }
            if pr >= 2.0 * nxt && nxt >= item_f {
                score -= 28.0 * (1.0 - (pr / (2.0 * nxt)).min(1.0));
            }
            if pr >= nxt + item_f {
