    if pr >= item_f && item_size > 0 && (pr % item_size) == 0 && pr < cap {
        score -= 20.0 * (pr / item_f).min(4.0);
    }

    // Reward bins whose residual equals the current item size exactly.
    if post_residual == 0 && bin_residual != bin_capacity && fitting_bins_count >= 1 {
        score -= 60.0 * (1.0 - item_ratio);
    }

    // NEW: residual-fitting lookahead — a residual that exactly absorbs the
    // next item plus the current item elsewhere is a strong consolidation
    // signal; reward proportional to how much of the residual is consumed.
    if next_item_size > 0 && pr >= next_item_size as f64 && pr < cap {
        let consumed = next_item_size as f64 / pr;
        score -= 25.0 * consumed * (1.0 - pr / cap);
    }

    // NEW: penalize residuals that are just barely too small for the next
    // item — they lock the bin into permanent dead space.
    if next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        let q = pr / next_item_size as f64;
        score += 40.0 * q * (1.0 - q);
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

    score
}

