        if pr < 0.25 * cap {
            let r = pr / cap;
            score += 145.0 * r * (1.0 - 4.0 * r) * (1.0 - r) + 25.0 * r * r;
        }
    }

    // Two-step lookahead with chain/divisibility anticipation.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
