            if pr - nxt >= item_f {
                score -= 42.0 * item_ratio;
            }
            if pr >= nxt + item_f {
                score -= 22.0 * (1.0 - ((pr - nxt - item_f) / cap).min(1.0));
            }
            // Divisibility chain: repeated next-items drain residual perfectly.
