pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in the "unusable" band
    // (small gaps that few future items can fill) is heavily penalized.
    let dead_zone: f64 = if post_residual > 0 && post_residual < 10 {
        60.0 // tiny slivers below the minimum item size are pure waste
    } else if post_residual >= 10 && post_residual < 25 {
        25.0 // hard-to-fill gap band
    } else if post_residual >= 25 && post_residual < 40 {
        8.0 // moderately awkward gap
    } else {
        0.0
    };
    score += dead_zone;

    // Reward near-perfect fits (post_residual very small but bin nearly full
    // overall is fine; penalize only if it strands space).
    if post_residual == 0 {
        score -= 40.0; // perfect pack
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Open-bins pressure: many open bins -> favor consolidating into them,
    // discouraging further bin proliferation.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual < bin_capacity {
        score -= 4.0 * pressure;
    } else {
        // New-bin candidate: only attractive when open bins are crowded
        // (low mean residual) and this bin would be the only fit.
        let crowded = mean_residual < (item_size as f64 + 5.0);
        score += 30.0;
        if crowded {
            score -= 45.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: opening is justified
        }
        // Late in the stream, prefer consolidation over new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // reward preserving that possibility; penalize if post_residual
    // blocks the next item while other bins could host it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0; // blocking next item with dead space
        }
    }

    // Mild tie-break: prefer bins whose residual is closest to the item
    // (tight fit) relative to the fleet mean.
    score -= ((bin_residual as f64 - item_size as f64) / 10.0).max(0.0);

    score
}

