    // Next item does NOT fit the post residual: penalize dead space,
    // especially if the dead space is small (unusable) rather than large (reusable).
    else if next_item_size > 0 && next_item_size > post_residual {
        let dead = post_residual as f64;
        // Small dead space (< 10) is nearly unusable -> heavy penalty.
        if dead < 10.0 {
            score += 40.0 + (10.0 - dead) * 4.0;
        } else {
            score += dead * 0.5;
        }
    }

