pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic classes of post_residual via capacity fractions (1/2, 1/3, 1/4, 1/6, 1/12)
    let cap_u = bin_capacity;
    let half = cap_u / 2;
    let third = cap_u / 3;
    let quarter = cap_u / 4;
    let sixth = cap_u / 6;
    let twelfth = cap_u / 12;

    // Reward residuals that fall into "usable" harmonic classes:
    // residual divisible into a large chunk class is likely to host a future item.
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if post_residual <= twelfth {
        score -= 18.0; // near-perfect sliver, negligible waste
    } else if post_residual >= sixth && post_residual <= third {
        // mid-band: often matches typical item sizes (10..80 range scaled)
        score -= 10.0;
    } else if post_residual == half {
        score -= 12.0; // exactly half: high reuse probability
    } else if post_residual > third && post_residual < half {
        score -= 6.0;
    } else if post_residual > half && post_residual <= 2 * third {
        score -= 3.0;
    } else {
        // large residual: penalize proportionally (wasteful bin)
        score += 0.05 * post;
    }

    // Integer-division threshold coupling: residual / item ratio classes
    if item_size > 0 {
        let ratio = post_residual / item_size;
        match ratio {
            0 => score -= 8.0,   // item dominates residual: tight fit
            1..=2 => score -= 4.0,
            3..=5 => score += 1.0,
            _ => score += 3.0,   // item tiny relative to bin: poor packing decision
        }
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0; // this placement enables next item (good chaining)
            // harmonic bonus if next item lands exactly on a class boundary
            if post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
        } else if next_item_size > post_residual && post_residual < quarter {
            score += 5.0; // leaves dead sliver that next item can't use
        }
    } else {
        // last item: reward any residual minimization strongly
        score += 0.5 * post;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer fresh bin when open bins are crowded
    // or this bin's residual is a bad harmonic class for the item.
    if bin_residual == bin_capacity {
        // neutral baseline: mean residual pressure decides
        let pressure = mean_residual / cap;
        score = 30.0 + 20.0 * pressure - 10.0 * (open_bins_count as f64).ln().max(0.0);
