        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * progress;
        if item_size > 2 * third {
            score -= 10.0; // very large item fits cleanly in fresh bin
        }
    }

    // Mild global pressure: when many bins open with large mean residual,
    // encourage consolidating into existing bins.
    if bin_residual != bin_capacity {
        score -= 0.02 * mean_residual;
        score += 0.5 * (open_bins_count as f64);
    }

    score
}

