            if rem >= item_f && k >= 1.0 {
                score -= 18.0 * (1.0 - (rem / cap).min(1.0));
            }
        } else {
            // Dead space the next item cannot use — super-linear penalty.
            let dead = pr;
            score += 0.65 * dead;
