    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins; prefer filling
    // existing bins when open_bins_count is already large.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += pressure * 4.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless post_residual creates a terrible gap).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual; make it
    // attractive only when existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; adjust by stream position and open-bin load.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * 0.55 - pressure * 6.0 + progress * 10.0;
