    // Penalize very small unusable leftovers (dead space) unless exact match handled above.
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Compare against mean residual: bins already tight are precious; loose bins should absorb items.
    if bin_residual < bin_capacity {
        let tightness = mean_residual - bin_residual as f64;
        score += 0.35 * tightness;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let early = step_index as f64 / (total_items.max(1) as f64);
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 18.0 };
        // Slight preference for new bins late in the stream (fewer future chances to fill them).
        score += desperation - 3.0 * early;
