    score += 2.6 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let slack = mean_residual / cap;
        score += 128.0 + 195.0 * progress + 165.0 * slack.max(0.0);

        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 75.0;
        }
        if item_ratio > 0.6 {
            score -= 58.0;
        }
        if fitting_bins_count <= 2 && item_ratio > 0.45 {
            score -= 36.0 * item_ratio;
        }
        if pr > 0.0 && pr < 0.2 * cap && fitting_bins_count <= 3 {
            score -= 100.0;
        }
        if progress > 0.85 && open_bins_count > 3 {
            score += 30.0 * progress;
        }
        if open_bins_count == 0 {
            score -= 42.0;
        }
        if item_ratio < 0.2 && progress > 0.5 {
            score += 48.0 * (1.0 - item_ratio * 5.0);
        }
        if next_item_size > 0 && next_item_size as f64 > 0.7 * cap && fitting_bins_count == 0 {
            score -= 60.0;
        }
        if mean_residual > 0.35 * cap && item_ratio < 0.5 {
            score += 55.0 * (mean_residual / cap - 0.35).min(0.4);
        }
        if progress < 0.2 && open_bins_count < 4 {
            score += 25.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual > 0.5 * cap {
            score += 45.0 * ((mean_residual / cap - 0.5) * 2.0).min(1.0);
        }
        if post_residual == 0 && fitting_bins_count >= 1 {
            score += 400.0;
        }
        if fitting_bins_count >= 1 && pr > 0.0 && pr < 0.12 * cap {
            score += 120.0 * (1.0 - pr / (0.12 * cap));
        }
        // NEW: avoid opening a fresh bin when the fresh bin's leftover (cap - item)
        // would itself be a near-miss sliver for the next item, while some open
        // bin could take the item — double waste avoidance.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let fresh_left = cap - item_f;
            if fresh_left > 0.0 && fresh_left < next_item_size as f64 {
                score += 90.0 * (1.0 - fresh_left / (next_item_size as f64));
            }
        }
    }

    // Harmonic coupling: prefer residuals near a future-fit size.
    if next_item_size > 0 && pr > 0.0 && pr != next_item_size as f64 {
        let dist = (pr - next_item_size as f64).abs() / cap;
        score += 18.0 * dist * (1.0 - dist);
    }

    // Endgame consolidation.
    if progress > 0.9 && pr > 0.0 {
        score -= 30.0 * (1.0 - pr / cap) * progress;
    }

    // Mid-stream consolidation: penalize odd slivers when many bins are open.
    if open_bins_count > 4 && pr > 0.0 && pr < 0.3 * cap {
        let frac = pr / cap;
        score += 55.0 * frac * (1.0 - frac) * (open_bins_count as f64 / 10.0).min(1.0);
    }

    // Self-sustaining chains of identical items.
    if pr >= item_f && item_size > 0 && (pr % item_size) == 0 && pr < cap {
        score -= 20.0 * (pr / item_f).min(4.0);
    }

    // Reward bins emptied exactly by the current item.
    if post_residual == 0 && bin_residual != bin_capacity && fitting_bins_count >= 1 {
        score -= 60.0 * (1.0 - item_ratio);
    }

    // NEW: reward exact-fit placements more when many bins are open — closing
    // bins reduces fragmentation pressure mid-stream.
    if post_residual == 0 && bin_residual != bin_capacity && open_bins_count > 3 {
        score -= 18.0 * (open_bins_count as f64 / 10.0).min(1.0);
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream: early on, be conservative (keep bins flexible);
    // late in stream, pack tighter and avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post_residual (tight fit), scaled nonlinearly.
    let tight_fit_bonus = (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;
    score += tight_fit_bonus;

    // Reward near-perfect fits strongly.
    if post_residual < 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0; // small unusable slivers
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item still fits here: keep residual usable
            let slack_after_next = post_residual - next_item_size;
            score -= 30.0 - (slack_after_next as f64) * 0.5;
        } else {
            // next item won't fit after this placement: mild penalty,
            // stronger early in stream when flexibility matters more.
            score += 8.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Global state coupling: many open bins with high mean residual ->
    // prefer filling existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        let crowding = open_bins_count as f64;
        score -= (mean_residual / bin_capacity as f64) * crowding.min(20.0) * 1.5;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when no open bin is a decent fit or residual is badly fragmented.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: high early, lower if the stream
        // is crowded with bins whose residuals are all small.
        let mut base = 55.0;
        if fitting_bins_count == 0 {
            base -= 60.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            base += 45.0; // a last-chance bin exists: avoid new bin
        } else {
            // compare item fit quality against mean residual of open bins
            let fit_ratio = item_size as f64 / bin_capacity as f64;
            if fit_ratio > 0.8 {
                base -= 20.0; // large item: fresh bin gives clean space
            }
            if mean_residual < item_size as f64 * 1.2 {
                base -= 15.0; // open bins barely fit: fresh bin reasonable
            }
        }
        // Late in the stream, discourage opening new bins harder.
        base += progress * 25.0;
        score += base;
    }

    // Slight penalty for very large items going into nearly full bins
    // when a roomier bin exists (keep big-item flexibility).
    if item_size > 60 && post_residual > 0 && post_residual < 20 {
        score += 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let item_ratio = item_size as f64 / cap;
    let item_f = item_size as f64;

    // Perfect fit: close the bin decisively.
    if post_residual == 0 {
        score -= 1150.0;
    }

    // Two-step lookahead.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 1010.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 370.0 * (1.0 - gap / cap);
            if next > 0.5 * cap && fitting_bins_count <= 2 {
                score -= 155.0 * (next / cap);
            }
            if pr >= 2.0 * next && pr < cap {
                score -= 58.0 * (1.0 - pr / cap);
            }
            if pr >= 3.0 * next {
                score -= 38.0 * (next / cap);
            }
            // Chain: residual hosts next item and still absorbs current-size items.
            if pr - next >= item_f {
                score -= 44.0 * item_ratio;
            }
            if pr >= 2.0 * next && next >= item_f {
                score -= 30.0 * (1.0 - (pr / (2.0 * next)).min(1.0));
            }
            if pr >= next + item_f {
                score -= 24.0 * (1.0 - ((pr - next - item_f) / cap).min(1.0));
            }
            // Triple chain — residual hosts next item twice (identical stream runs).
            if pr >= 2.0 * next && next > item_f {
                score -= 22.0 * (next / cap);
            }
            // Divisibility chain — residual is an exact multiple of the next
            // item, so repeated next-items will drain it perfectly.
            if next > 0 && (post_residual % next_item_size) == 0 && pr < cap {
                score -= 34.0 * (pr / next).min(4.0);
            }
            // NEW: near-divisibility — residual within a couple units of an exact
            // multiple of next; a slightly larger later item can close it.
            if next > 0 && pr < cap {
                let k = (pr / next).floor();
                let rem = pr - k * next;
                if k >= 1.0 && rem > 0.0 && rem <= 4.0 {
                    score -= 14.0 * (1.0 - rem / 4.0);
                }
            }
        } else {
            // Dead space the next item cannot use — super-linear penalty.
            let dead = pr;
            score += 0.68 * dead;
            if dead > 0.0 && dead < next {
                let q = dead / next;
                score += 105.0 * q * (1.0 - q) + 68.0 * (1.0 - q);
                score += 48.0 * q * (next / cap);
            }
        }
        if bin_residual == bin_capacity && next_item_size == item_size {
            score -= 42.0;
        }
    }

    // Quartic dead-space penalty in the awkward zone.
    if pr > 0.0 && pr < 0.25 * cap {
        let r = pr / cap;
        score += 150.0 * r * (1.0 - 4.0 * r) * (1.0 - r) + 26.0 * r * r;
    }

    // Tightness reward with concave saturation.
    let tightness = item_f / (bin_residual.max(1) as f64);
    score -= 10.0 * (1.0 - (-2.0 * tightness).exp());

    // Tight-packing bias around the mean residual.
    score += 0.38 * (pr - mean_residual).max(0.0);
    score -= 0.16 * (mean_residual - pr).max(0.0);

    // Waste-ratio coupling, non-linear.
    let post_ratio = pr / cap;
    score += 72.0 * item_ratio * post_ratio * (1.0 + 0.5 * post_ratio);

    // Usable residuals keep future options open.
    if pr >= mean_residual {
        score -= 33.0 * ((pr - mean_residual) / cap).min(0.25);
    }

    // Near-miss residual penalty.
    if next_item_size > 0 && pr > 0.0 {
        let next = next_item_size as f64;
        let miss = (pr - next).abs();
        if miss > 0.0 && miss < 0.08 * cap {
            score += 62.0 * (1.0 - miss / (0.08 * cap));
        }
    }

    // Open-bin pressure, stronger late in stream.
    score += 2.6 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let slack = mean_residual / cap;
        score += 130.0 + 198.0 * progress + 168.0 * slack.max(0.0);

        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 78.0;
        }
        if item_ratio > 0.6 {
            score -= 60.0;
        }
        if fitting_bins_count <= 2 && item_ratio > 0.45 {
            score -= 38.0 * item_ratio;
        }
        if pr > 0.0 && pr < 0.2 * cap && fitting_bins_count <= 3 {
            score -= 102.0;
        }
        if progress > 0.85 && open_bins_count > 3 {
            score += 32.0 * progress;
        }
        if open_bins_count == 0 {
            score -= 44.0;
        }
        if item_ratio < 0.2 && progress > 0.5 {
            score += 50.0 * (1.0 - item_ratio * 5.0);
        }
        if next_item_size > 0 && next_item_size as f64 > 0.7 * cap && fitting_bins_count == 0 {
            score -= 62.0;
        }
        if mean_residual > 0.35 * cap && item_ratio < 0.5 {
            score += 57.0 * (mean_residual / cap - 0.35).min(0.4);
        }
        if progress < 0.2 && open_bins_count < 4 {
            score += 26.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual > 0.5 * cap {
            score += 47.0 * ((mean_residual / cap - 0.5) * 2.0).min(1.0);
        }
        // Opening a fresh bin is wasteful when an existing bin would close exactly.
        if post_residual == 0 && fitting_bins_count >= 1 {
            score += 410.0;
        }
        // Never open a new bin when the item nearly fills some existing bin
        // (post_residual is a small sliver) — slivers are the dominant waste mode.
        if fitting_bins_count >= 1 && pr > 0.0 && pr < 0.12 * cap {
            score += 125.0 * (1.0 - pr / (0.12 * cap));
        }
        // NEW: refuse new bins while open bins still have room matching the
        // next item's size — preserves chainability instead of fragmenting.
        if next_item_size > 0 && fitting_bins_count >= 1 && open_bins_count >= 1 {
            let next = next_item_size as f64;
            let mut match_bonus = 0.0;
            if (post_residual as i64 - next as i64).abs() <= 3 {
                match_bonus += 90.0;
            }
            if next >= pr {
                match_bonus += 35.0 * (1.0 - (next - pr) / cap);
            }
            score += match_bonus * (0.6 + 0.4 * progress);
        }
    }

    // Harmonic coupling: prefer residuals near a future-fit size.
    if next_item_size > 0 && pr > 0.0 && pr != next_item_size as f64 {
        let dist = (pr - next_item_size as f64).abs() / cap;
        score += 18.0 * dist * (1.0 - dist);
    }

    // Endgame consolidation.
    if progress > 0.9 && pr > 0.0 {
        score -= 32.0 * (1.0 - pr / cap) * progress;
    }

    // Mid-stream consolidation: penalize odd slivers when many bins are open.
    if open_bins_count > 4 && pr > 0.0 && pr < 0.3 * cap {
        let frac = pr / cap;
        score += 58.0 * frac * (1.0 - frac) * (open_bins_count as f64 / 10.0).min(1.0);
    }

    // Self-sustaining chains of identical items.
    if pr >= item_f && item_size > 0 && (pr % item_size) == 0 && pr < cap {
        score -= 22.0 * (pr / item_f).min(4.0);
    }

    // Reward bins whose residual equals the current item size exactly
    // (this placement empties the bin) even when next_item differs.
    if post_residual == 0 && bin_residual != bin_capacity && fitting_bins_count >= 1 {
        score -= 62.0 * (1.0 - item_ratio);
    }

    // NEW: quadratic dead-space ratio coupling — bins left with residuals in the
    // mid-range (neither nearly full nor roomy) are the worst future hosts.
    if pr > 0.0 && pr < cap {
        let mid = 1.0 - (2.0 * post_ratio - 1.0).abs();
        score += 12.0 * mid * mid * (1.0 - progress);
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement, mildly discounted as stream progresses
    // (later on, tightening fills matter more, so waste is penalized harder).
    let mut score = pr * (1.0 + 0.6 * progress);

    // Non-linear polynomial coupling of post_residual with progress:
    // mid-stream, medium residuals are acceptable; late-stream, tiny residuals are gold.
    let prn = pr / cap; // normalized post residual in [0,1]
    let t = progress;
    let coupling = prn * prn * (1.0 - prn) * (1.0 - prn);
    score += 12.0 * coupling * (1.0 + 3.0 * t);

    // Reward near-perfect fills with a strong smooth bump.
    let perfect = (1.0 - prn).powi(6);
    score -= 20.0 * perfect;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * t;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 4.0 + 3.0 * fit_quality;
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty proportional to leftover.
        score += 2.0 * prn;
    }

    // Penalize spreading across many open bins when mean residual is large.
    let open_pressure = (open_bins_count as f64).ln() * (mean_residual / cap);
    score += 1.5 * open_pressure;

    // New-bin candidate should look unattractive unless residuals are hopeless.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - t) + 2.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
