    let item_ratio = item_size as f64 / cap;
    let item_f = item_size as f64;

    // Perfect fill: bin closes exactly.
    if post_residual == 0 {
        score -= 1150.0;
    }

    // Graded dead-space penalties.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 400.0;
        } else if post_residual < 20 {
            score += 120.0;
        } else if post_residual < 35 {
            score += 30.0;
        } else if post_residual < 50 {
            score += 6.0;
        }
        let tightness = 1.0 - (post_residual as f64 / cap);
        score -= 15.0 * tightness * tightness;
        // Quartic dead-space penalty in the awkward zone.
        if pr < 0.25 * cap {
            let r = pr / cap;
            score += 145.0 * r * (1.0 - 4.0 * r) * (1.0 - r) + 25.0 * r * r;
        }
    }

    // Two-step lookahead with chain rewards.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 330.0 * (1.0 - gap / cap);
            if nxt > 0.5 * cap && fitting_bins_count <= 2 {
                score -= 130.0 * (nxt / cap);
            }
            // Divisibility chain: residual is an exact multiple of next item.
            if (post_residual % next_item_size) == 0 && pr < cap {
                score -= 30.0 * (pr / nxt).min(4.0);
            }
            // Residual hosts next item and still absorbs current-size items.
            if pr - nxt >= item_f {
                score -= 40.0 * item_ratio;
            }
            if pr >= nxt + item_f {
                score -= 20.0 * (1.0 - ((pr - nxt - item_f) / cap).min(1.0));
            }
        } else {
            let dead = pr;
            score += 0.6 * dead;
            if dead > 0.0 && dead < nxt {
                let q = dead / nxt;
                score += 95.0 * q * (1.0 - q) + 60.0 * (1.0 - q);
                score += 40.0 * q * (nxt / cap);
            }
        }
        // Near-miss residual penalty.
        if pr > 0.0 {
            let miss = (pr - nxt).abs();
            if miss > 0.0 && miss < 0.08 * cap {
                score += 55.0 * (1.0 - miss / (0.08 * cap));
            }
