    }

    // Tightness coupling with concave saturation.
    let tightness = item_f / (bin_residual.max(1) as f64);
    score -= 9.0 * (1.0 - (-2.0 * tightness).exp());

    // Waste-ratio coupling, non-linear.
    let post_ratio = pr / cap;
    score += 65.0 * item_ratio * post_ratio * (1.0 + 0.5 * post_ratio);

    // Residual positioning vs mean.
    score += 0.35 * (pr - mean_residual).max(0.0);
    score -= 0.14 * (mean_residual - pr).max(0.0);
    if (bin_residual as f64) > mean_residual {
        score -= 6.0;
    }

    // Usable residuals keep future options open.
    if pr >= mean_residual && pr > 0.0 {
        score -= 28.0 * (((pr - mean_residual) / cap).min(0.25));
    }

    // Last-chance pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 240.0;
    }

    // Open-bin pressure, stronger late.
    score += 2.4 * open_bins_count as f64 * (0.5 + progress);

    // Mid-stream sliver pressure when many bins open.
    if open_bins_count > 4 && pr > 0.0 && pr < 0.3 * cap {
        let frac = pr / cap;
        score += 50.0 * frac * (1.0 - frac) * (open_bins_count as f64 / 10.0).min(1.0);
    }

    // Self-sustaining chains of identical items.
    if pr >= item_f && item_size > 0 && (pr % item_size) == 0 && pr < cap {
        score -= 20.0 * (pr / item_f).min(4.0);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let slack = mean_residual / cap;
        score += 125.0 + 190.0 * progress + 160.0 * slack.max(0.0);

        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 70.0;
        }
        if item_ratio > 0.6 {
            score -= 50.0;
        }
        if fitting_bins_count <= 2 && item_ratio > 0.45 {
            score -= 32.0 * item_ratio;
        }
        // All-wasty relaxation.
        if pr > 0.0 && pr < 0.2 * cap && fitting_bins_count <= 3 {
            score -= 90.0;
        }
        if open_bins_count == 0 {
            score -= 42.0;
        }
        // Late-stream small leftovers should not open new bins.
        if progress > 0.7 && item_size < 30 {
            score += 80.0;
        }
        // Never open a new bin when an existing bin would close exactly.
        if post_residual == 0 && fitting_bins_count >= 1 {
            score += 400.0;
        }
        // Sliver guard: prefer existing bins leaving near-zero waste.
        if fitting_bins_count >= 1 && pr > 0.0 && pr < 0.12 * cap {
            score += 110.0 * (1.0 - pr / (0.12 * cap));
        }
        // Small items mid-stream: squeeze into open bins.
        if item_ratio < 0.2 && progress > 0.5 {
            score += 45.0 * (1.0 - item_ratio * 5.0);
        }
        // Many open bins with large mean residual: consolidate.
        if open_bins_count > 5 && mean_residual > 0.5 * cap {
            score += 40.0 * ((mean_residual / cap - 0.5) * 2.0).min(1.0);
        }
    }

    // Endgame consolidation.
    if progress > 0.9 && pr > 0.0 {
        score -= 28.0 * (1.0 - pr / cap) * progress;
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

