    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quarter classes of capacity.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..3 for open bins
    match class {
        0 => score -= 14.0,           // nearly full: excellent
        1 => score += 4.0,            // half-ish: mildly bad
        2 => score += 10.0,           // poor
        _ => score += 18.0,           // mostly empty: wasteful
    }

    // Fine-grained tightness: reward exact/near-exact fits.
    if post_residual == 0 { score -= 25.0; }
    else if post_residual <= 5 { score -= 12.0; }
    else if post_residual <= 10 { score -= 6.0; }

    // Lookahead coupling: does the next item fit into this bin's residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // Extra reward if next item exactly consumes the residual class.
        if post_residual - next_item_size <= 5 { score -= 6.0; }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Residual becomes dead space for the next item: penalize proportionally.
        score += 0.25 * (next_item_size as f64 - post_residual as f64).min(20.0);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: default neutral-ish; discourage unless
    // existing bins are all poor fits (few fitting bins, high mean residual).
    if bin_residual == bin_capacity {
        score = cap * 0.55; // baseline ~55
        let scarcity = (fitting_bins_count as f64).max(1.0);
        score -= 18.0 / scarcity;                 // fewer options -> cheaper new bin
        score += 0.35 * (mean_residual - cap * 0.4).max(0.0); // rich residuals -> keep packing
