        score += 12.0 * progress;
        // If next item is huge, a fresh bin is attractive.
        if next_item_size >= bin_capacity / 2 { score -= 10.0; }
    }

    // Mild penalty for bin proliferation: prefer filling existing bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
