            if pr >= 2.0 * next && pr < cap {
                score -= 55.0 * (1.0 - pr / cap);
            }
            if pr >= 3.0 * next {
                score -= 35.0 * (next / cap);
            }
            // Chain: residual hosts next item and still absorbs current-size items.
            if pr - next >= item_f {
                score -= 42.0 * item_ratio;
            }
            if pr >= 2.0 * next && next >= item_f {
                score -= 28.0 * (1.0 - (pr / (2.0 * next)).min(1.0));
            }
            if pr >= next + item_f {
                score -= 22.0 * (1.0 - ((pr - next - item_f) / cap).min(1.0));
            }
