    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by 10 are "usable"
    // by typical item sizes; odd/small residues are dead space.
    let r = post_residual % 10;
    if r == 0 {
        score -= 6.0; // perfectly aligned residual, likely reusable
    } else if r <= 2 {
        score += 3.0; // nearly dead space
    } else {
        score += (10 - r) as f64 * 0.4; // penalize misalignment
