    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // pair-friendly: reward if post_residual is in a harmonic class
            // matching next_item_size's class (same decade alignment)
            let cls_next = (next_item_size / 10) as f64;
            let cls_post = (post_residual / 10) as f64;
            score -= 5.0 + 0.5 * (cls_next - cls_post).abs().min(3.0);
        } else {
            score += 4.0; // next item cannot follow here
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
