        score -= 15.0 * (1.0 - ((pr - next_item_size as f64 - item_f) / cap).min(1.0));
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that cannot hold even the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Small-but-usable gaps are also risky for future large items.
    if post_residual >= 10 && post_residual < 25 {
        score += 6.0;
    }

    // Reward near-perfect packing more aggressively than linear.
    if post_residual == 0 {
        score -= 25.0;
    } else if item_size as f64 / bin_capacity as f64 > 0.8 && post_residual < 20 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement chains nicely -> strong reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 12.0;
    }
    // Penalize leaving a gap that just barely misses the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + item_size as f64 * 0.1;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading (helps new-bin candidate lose).
    score += (open_bins_count as f64).sqrt() * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Deviation from mean residual: prefer bins that are already fuller
    // than average (small residuals relative to mean).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Slight early-stream conservatism: keep bins flexible early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * post_residual as f64 * 0.1;

    // New-bin candidate: make the empty bin attractive only when the item
    // is large (would leave little residual anyway) or nothing fits well.
    if bin_residual == bin_capacity {
        if item_size >= 70 {
            score -= 15.0;
        } else {
            score += 5.0 + (100 - item_size) as f64 * 0.2;
        }
    }

    score
}

