pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "reusable" the leftover space is.
    // Residuals divisible by common item-size classes (multiples of 5, 10, 20)
    // are more likely to be filled by future items.
    let pr = post_residual;
    let mut harmony_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { harmony_bonus += 6.0; }
        else if pr % 5 == 0 { harmony_bonus += 3.0; }
        if pr % 20 == 0 { harmony_bonus += 3.0; }
        if pr % 25 == 0 { harmony_bonus += 2.0; }
        // Very small dead space is nearly perfect
        if pr <= 3 { harmony_bonus += 10.0; }
        else if pr <= 8 { harmony_bonus += 4.0; }
        // Dead zones: residuals in awkward mid ranges are hard to fill
        if pr >= 31 && pr <= 39 { harmony_bonus -= 5.0; }
        if pr >= 61 && pr <= 69 { harmony_bonus -= 3.0; }
    } else {
        harmony_bonus += 14.0; // perfect fit
    }
    score -= harmony_bonus;

    // Fractional fill of the bin: reward tight packing nonlinearly.
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 8.0 * fill * fill;

    // Lookahead coupling: if the next item fits harmonically in post_residual,
    // strongly favor this bin (chained placement).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if next_item_size <= pr {
            let chained_post = pr - next_item_size;
            if chained_post % 10 == 0 { score -= 4.0; }
            if chained_post <= 5 { score -= 3.0; }
        } else {
            // next item cannot use the leftover: penalize large leftovers less
            // if they at least form a harmonic class
            if pr % 10 != 0 && pr > 20 { score += 2.0; }
        }
        // If next item would need a fresh bin anyway, prefer keeping residuals
        // in big harmonic chunks (multiples of 20)
        if next_item_size > pr && pr % 20 == 0 && pr > 0 { score -= 2.0; }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0 + 0.05 * open_bins_count as f64;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large and current open bins would be left with ugly residuals.
    if bin_residual == bin_capacity {
        let ugly_current = mean_residual > 0.0 && mean_residual < 20.0;
        if item_size >= bin_capacity / 2 || ugly_current {
            score -= 6.0;
        } else {
            score += 9.0 + 0.3 * open_bins_count as f64;
        }
        // Late in the stream, prefer consolidating into open bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 4.0;
        }
    }

    // Mild pressure to prefer filling bins with small residuals overall.
    score -= 0.02 * (bin_capacity as f64 - bin_residual as f64);

    // Mean-residual alignment: bins whose residual is close to the mean keep
    // the bin population homogeneous and easy to match.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    score
}

