pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (>=1) can use are pure waste,
    // but small "hard-to-fill" gaps are the real killers. Penalize unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space below the minimum item size
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0; // narrow window, hard to pair
    } else if post_residual >= 20 && post_residual <= 40 {
        score -= 8.0; // useful mid-range gap, mildly rewarded
    } else if post_residual > 40 {
        score += 4.0; // large leftover = item was small, bin underutilized
    }

    // Reward tight fits (exact or near-exact) strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 20.0 * tightness;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is excellent; if post residual can't hold the next item
    // while some other gap could, mildly penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            score += 6.0;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> consolidate; few open bins -> opening
    // a new bin is cheap so don't overstuff.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
