    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * (post_residual - next_item_size) as f64;
        } else {
            // Penalize leaving a residual that is useless for the next item,
            // scaled by how much dead space would be stranded.
            let waste = post_residual as f64;
            score += 0.10 * waste;
