    }

    // Penalize bins far from the mean residual (prefer balanced or very full bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: prefer opening a new bin only when it's early in the
    // stream or all existing fits are poor (large post_residual elsewhere).
    if bin_residual == bin_capacity {
        // Base mild penalty so we prefer reusing bins with decent fits.
        score += 10.0;
