        if dead_ratio > 0.5 {
            score += 40.0 * (dead_ratio - 0.5) * (1.0 - pr / cap);
        }
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Residuals divisible into coarse capacity fractions are more reusable.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Class A: post_residual >= 50 (can still hold half the stream) -> strong reward
    if post_residual >= bin_capacity / 2 {
        score -= 6.0 * frac;
    }
    // Class B: post_residual in [30, 50) -> moderate reward
    else if post_residual >= bin_capacity / 4 {
        score -= 2.5 * frac;
    }
    // Class C: post_residual in [10, 30) -> mild reward
    else if post_residual >= 10 {
        score -= 0.8 * frac;
    }
    // Class D: tiny dead space < 10 -> penalize
    else if post_residual > 0 {
        score += 4.0 * (1.0 - frac);
    }

    // Harmonic residue: post_residual mod 10 — multiples of 10 align with
    // typical item granularities, so leftovers on the 10-grid are reusable.
    let residue = post_residual % 10;
    if residue == 0 {
        score -= 2.0;
    } else {
        score += 0.6 * residue as f64;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward tight follow-up fits; penalize if next item would leave
            // another tiny dead zone.
            score -= 3.0;
            if slack < 10.0 {
                score += 0.5 * slack;
            }
        } else {
            // Next item cannot use this residual at all: mild penalty scaled
            // by how much space would be stranded.
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity elsewhere.
    // Only prefer a fresh bin when all open bins would strand lots of space.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // If mean residual across open bins is high, prefer reusing them.
        score += 30.0 * pressure;
        // Early in stream, opening bins is fine; later, discourage.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
        // If the item would leave a large residual anyway, new bin is OK.
        if item_size <= bin_capacity / 4 {
            score -= 5.0;
        }
    }

    // Congestion: with many open bins, prefer filling existing ones.
    score += 0.15 * open_bins_count as f64 * (1.0 - frac);

    // Prefer bins with below-mean residual (more packed bins get packed further).
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual && bin_residual < bin_capacity {
        score -= 1.5;
    } else if bin_res_f > mean_residual * 1.5 {
        score += 1.0;
    }

    score
}

