            score -= 980.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 360.0 * (1.0 - gap / cap);
            if next > 0.5 * cap && fitting_bins_count <= 2 {
                score -= 150.0 * (next / cap);
            }
            if pr >= 2.0 * next && pr < cap {
                score -= 55.0 * (1.0 - pr / cap);
            }
            if pr >= 3.0 * next {
                score -= 35.0 * (next / cap);
            }
            // Chain: residual hosts next item and still absorbs current-size items.
            if pr - next >= item_f {
                score -= 42.0 * item_ratio;
            }
            if pr >= 2.0 * next && next >= item_f {
                score -= 28.0 * (1.0 - (pr / (2.0 * next)).min(1.0));
            }
            if pr >= next + item_f {
                score -= 22.0 * (1.0 - ((pr - next - item_f) / cap).min(1.0));
            }
            // Triple chain — residual hosts next item twice (identical stream runs).
            if pr >= 2.0 * next && next > item_f {
                score -= 20.0 * (next / cap);
            }
            // Divisibility chain — residual is an exact multiple of the next item.
            if next > 0 && (post_residual % next_item_size) == 0 && pr < cap {
                score -= 30.0 * (pr / next).min(4.0);
            }
            // Two-item lookahead — residual absorbs next item AND the current
            // item afterwards, exactly draining itself (next + item == pr).
            if (pr - next - item_f).abs() < 1.0 && pr >= next + item_f {
                score -= 85.0;
            }
            // Residual fits next item with a small useful remainder matching
            // the current item size class (coupled pair planning).
            let rem = pr - next;
            if rem >= item_f && rem < item_f * 2.5 {
                score -= 18.0 * (1.0 - rem / (2.5 * item_f).max(1.0));
            }
            // NEW: exact-drain planning — pr equals k*next + m*item for small k,m.
            let mut drained = false;
            for k in 1..5u32 {
                for m in 0..4u32 {
                    if pr as u32 == k * next_item_size + m * item_size {
                        drained = true;
                    }
                }
            }
            if drained {
                score -= 50.0 * (1.0 - item_ratio);
            }
            // NEW: reward leaving a residual that is itself a "nice" size —
            // close to a divisor-friendly value (near multiples of small units).
            let unit = if next < item_f { next } else { item_f };
            if unit > 0.0 {
                let near_mult = (pr / unit).round() * unit;
                let dev = (pr - near_mult).abs();
                if dev < 0.03 * cap && pr >= unit {
                    score -= 14.0 * (1.0 - dev / (0.03 * cap));
                }
            }
        } else {
            // Dead space the next item cannot use — super-linear penalty.
            let dead = pr;
            score += 0.65 * dead;
            if dead > 0.0 && dead < next {
                let q = dead / next;
                score += 100.0 * q * (1.0 - q) + 65.0 * (1.0 - q);
                score += 45.0 * q * (next / cap);
