    if pr > 0.0 && pr < cap && open_bins_count > 2 {
        let dup = ((pr - mean_residual).abs() / cap) < 0.02;
        if dup {
            score += 12.0 * (1.0 - progress);
        }
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

    score
}

