    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item size (perfect 2-chain), penalize near-miss waste.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            // next item fits here after this one; better the tighter the fit
            score -= 25.0 / (1.0 + diff / 20.0);
        } else {
            // next item cannot follow; dead space grows the smaller the gap
            score += (next_item_size as f64 - post_residual as f64) * 0.35;
        }

        // Coupling with mean residual: prefer bins whose post state tracks the fleet mean
        score += (post_residual as f64 - mean_residual).abs() * 0.15;
    } else {
        // Last item: minimize waste aggressively
        score *= 1.5;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Slight penalty when many bins are open: consolidate to limit bin count
    score += open_bins_count as f64 * 0.05;

    // Prefer fuller bins overall (lower residual before placement)
    score += (bin_capacity as f64 - bin_residual as f64).abs() * 0.02;

    // Late-stream consolidation pressure
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * progress;

    score
}

