    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is very poor.
    if bin_residual == bin_capacity {
        let crowdedness = if open_bins_count > 0 {
            1.0 - (mean_residual / bin_capacity as f64)
