    // useful (below the smallest plausible item) are heavily penalized,
    // but a perfect fit (0) is rewarded.
    if post_residual == 0 {
        score -= 50.0; // perfect closure
    } else if post_residual < 10 {
        score += 30.0; // dead space, unusable
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item granularities are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 15.0 * (1.0 - chain_waste as f64 / cap);
        } else {
            // next item cannot use this residual at all: slight penalty
            // proportional to how stranded the residual is.
            score += 5.0 * (post_class / 10.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when existing residuals
    // are poor (fragmented) or no bins exist yet.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.9;
        // Cheaper to open a new bin when mean residual across open bins is
        // fragmented (small mean residual) or few fitting options exist.
        score -= (mean_residual / cap) * 30.0;
        if fitting_bins_count == 0 {
            score -= cap; // forced new bin
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Large items keep a fresh bin useful; small items waste a new bin.
        score -= (item_size as f64 / cap) * 15.0;
    }

    // Prefer tighter bins generally: reward small current residual
    // (best-fit flavor) scaled by how full the bin already is.
    score += (bin_residual as f64 / cap) * 6.0;

    // Mild pressure against accumulating many open bins with fat residuals.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item_f = item_size as f64;
    let item_ratio = item_f / cap;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = pr;

    // Perfect fill: decisive closure.
    if post_residual == 0 {
        score -= 1150.0;
    }

    // Dead-space avoidance: harsh graded penalties on unusable gaps.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 900.0;
        } else if post_residual < 20 {
            score += 220.0;
        } else if post_residual < 35 {
            score += 45.0;
        } else if post_residual < 50 {
            score += 9.0;
        }
        // Quartic awkward-zone penalty (0..25% of capacity).
        if pr < 0.25 * cap {
            let r = pr / cap;
            score += 145.0 * r * (1.0 - 4.0 * r) * (1.0 - r) + 25.0 * r * r;
        }
    }

    // Two-step lookahead around next_item_size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 980.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 360.0 * (1.0 - gap / cap);
            if next > 0.5 * cap && fitting_bins_count <= 2 {
                score -= 150.0 * (next / cap);
            }
            // Multi-copy drain: residual hosts several next-items.
            if pr >= 2.0 * next && pr < cap {
                score -= 55.0 * (1.0 - pr / cap);
            }
            if pr >= 3.0 * next {
                score -= 35.0 * (next / cap);
            }
            // Divisibility chain: residual drains perfectly over repeated next-items.
            if (post_residual % next_item_size) == 0 && pr < cap {
                score -= 30.0 * (pr / next).min(4.0);
            }
            // Chain: residual hosts next item and still absorbs current-size items.
            if pr - next >= item_f {
                score -= 42.0 * item_ratio;
            }
            if pr >= next + item_f {
                score -= 22.0 * (1.0 - ((pr - next - item_f) / cap).min(1.0));
            }
            if pr >= 2.0 * next && next > item_f {
                score -= 20.0 * (next / cap);
            }
            // Exact two-item drain: residual == next + item.
            if (pr - next - item_f).abs() < 1.0 && pr >= next + item_f {
                score -= 85.0;
            }
            // Residual fits next item, remainder matches current item class.
            let rem = pr - next;
            if rem >= item_f && rem < item_f * 2.5 {
                score -= 18.0 * (1.0 - rem / (2.5 * item_f).max(1.0));
            }
        } else {
            // Dead space the next item cannot use: super-linear penalty.
            let q = pr / next;
            score += 100.0 * q * (1.0 - q) + 65.0 * (1.0 - q);
            score += 45.0 * q * (next / cap);
        }
        // Near-miss residual penalty.
        if pr > 0.0 {
            let miss = (pr - next).abs();
            if miss > 0.0 && miss < 0.10 * cap {
                score += 60.0 * (1.0 - miss / (0.10 * cap));
            }
        }
        if bin_residual == bin_capacity && next_item_size == item_size {
            score -= 40.0;
        }
    }

    // Harmonic coupling: prefer residuals near a future-fit size.
    if next_item_size > 0 && pr > 0.0 && pr != next_item_size as f64 {
        let dist = (pr - next_item_size as f64).abs() / cap;
        score += 18.0 * dist * (1.0 - dist);
    }

    // Anti-fragmentation: penalize residuals no plausible future item can pair with.
    if next_item_size > 0 && pr > 0.0 && pr < cap {
        let next = next_item_size as f64;
        let pairable = pr >= next || pr >= item_f || (pr + next) as u32 <= bin_capacity;
        if !pairable {
            score += 35.0 * (1.0 - pr / cap);
        }
    }

    // Tightness reward with concave saturation.
    let tightness = item_f / (bin_residual.max(1) as f64);
    score -= 10.0 * (1.0 - (-2.0 * tightness).exp());

    // Tight-packing bias around the mean residual.
    score += 0.38 * (pr - mean_residual).max(0.0);
    score -= 0.16 * (mean_residual - pr).max(0.0);

    // Waste-ratio coupling, non-linear.
    let post_ratio = pr / cap;
    score += 70.0 * item_ratio * post_ratio * (1.0 + 0.5 * post_ratio);

    // Usable residuals keep future options open.
    if pr >= mean_residual {
        score -= 32.0 * ((pr - mean_residual) / cap).min(0.25);
    }

    // Open-bin pressure, stronger late in stream.
    score += 2.6 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Mid-stream consolidation: penalize odd slivers when many bins are open.
    if open_bins_count > 4 && pr > 0.0 && pr < 0.3 * cap {
        let frac = pr / cap;
        score += 55.0 * frac * (1.0 - frac) * (open_bins_count as f64 / 10.0).min(1.0);
    }

    // Self-sustaining chains of identical items.
    if item_size > 0 && pr >= item_f && (pr as u32 % item_size) == 0 && pr < cap {
        score -= 20.0 * (pr / item_f).min(4.0);
    }

    // Reward exact-emptiness placements even when next_item differs.
    if post_residual == 0 && bin_residual != bin_capacity && fitting_bins_count >= 1 {
        score -= 60.0 * (1.0 - item_ratio);
    }

    // Endgame consolidation.
    if progress > 0.9 && pr > 0.0 {
        score -= 30.0 * (1.0 - pr / cap) * progress;
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let slack = mean_residual / cap;
        score += 128.0 + 195.0 * progress + 165.0 * slack.max(0.0);

        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 75.0;
        }
        if item_ratio > 0.6 {
            score -= 58.0;
        }
        if fitting_bins_count <= 2 && item_ratio > 0.45 {
            score -= 36.0 * item_ratio;
        }
        if pr > 0.0 && pr < 0.2 * cap && fitting_bins_count <= 3 {
            score -= 100.0;
        }
        if progress > 0.85 && open_bins_count > 3 {
            score += 30.0 * progress;
        }
        if open_bins_count == 0 {
            score -= 42.0;
        }
        if item_ratio < 0.2 && progress > 0.5 {
            score += 48.0 * (1.0 - item_ratio * 5.0);
        }
        if next_item_size > 0 && next_item_size as f64 > 0.7 * cap && fitting_bins_count == 0 {
            score -= 60.0;
        }
        if mean_residual > 0.35 * cap && item_ratio < 0.5 {
            score += 55.0 * (mean_residual / cap - 0.35).min(0.4);
        }
        if progress < 0.2 && open_bins_count < 4 {
            score += 25.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual > 0.5 * cap {
            score += 45.0 * ((mean_residual / cap - 0.5) * 2.0).min(1.0);
        }
        // Never open a new bin when an existing bin would close exactly.
        if post_residual == 0 && fitting_bins_count >= 1 {
            score += 400.0;
        }
        // Never open a new bin when the item nearly fills some existing bin
        // (slivers are the dominant waste mode).
        if fitting_bins_count >= 1 && pr > 0.0 && pr < 0.12 * cap {
            score += 120.0 * (1.0 - pr / (0.12 * cap));
        }
        // Forbid new bins when a perfect closure exists late in stream.
        if post_residual == 0 && progress > 0.7 {
            score += 150.0 * progress;
        }
        // Resist opening new bins when existing residuals can host next item too.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let next = next_item_size as f64;
            if pr >= next {
                score += 45.0 * progress;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let gap = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Exact fit: overwhelming reward, essentially always take it.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: exponential penalty that peaks for tiny,
    // nearly unusable nonzero gaps and vanishes for large (still useful) ones.
    // The penalty tightens as more bins are open (fragmentation pressure)
    // and as the stream progresses (less future opportunity to fill gaps).
    if post_residual > 0 {
        let dead = 40.0 * (-gap / 12.0).exp();
        score += dead * (1.0 + 0.05 * open_bins_count as f64) * (1.0 + progress);
    }

    // Lookahead coupling (k=2): reward bins whose leftover can also host the
    // next item; penalize leftovers too small for it (guaranteed dead space).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if gap >= n {
            score -= 0.6 * n;
        } else if post_residual > 0 {
            score += 0.25 * (n - gap);
        }
    }

    if is_new_bin {
        // New-bin candidate: penalize proliferation of open bins, more so
        // late in the stream, plus a small constant deterrent so that any
        // decent existing fit is preferred over opening a fresh bin.
        score += 3.0 * open_bins_count as f64
               + 15.0 * progress
               + 5.0
               + 0.05 * mean_residual;
    } else {
        // Last-chance bin: strongly prefer using it over opening a new bin.
        if fitting_bins_count == 1 {
            score -= 120.0;
        } else {
            // Mild reward when few bins can host the item.
            score -= 8.0 / (fitting_bins_count.max(1) as f64);
        }
        // Consolidation: prefer bins tighter than the current mean residual.
        score -= 0.1 * (mean_residual - gap);
    }

    score
}

