            score -= 75.0;
        }
        if item_ratio > 0.6 {
            score -= 58.0;
        }
        if fitting_bins_count <= 2 && item_ratio > 0.45 {
            score -= 36.0 * item_ratio;
        }
        if pr > 0.0 && pr < 0.2 * cap && fitting_bins_count <= 3 {
            score -= 100.0;
        }
        if open_bins_count == 0 {
            score -= 42.0;
        }
        if item_ratio < 0.2 && progress > 0.5 {
            score += 48.0 * (1.0 - item_ratio * 5.0);
        }
        if next_item_size > 0 && next_item_size as f64 > 0.7 * cap && fitting_bins_count == 0 {
            score -= 60.0;
        }
        if mean_residual > 0.35 * cap && item_ratio < 0.5 {
            score += 55.0 * (mean_residual / cap - 0.35).min(0.4);
        }
        if progress < 0.2 && open_bins_count < 4 {
            score += 25.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual > 0.5 * cap {
            score += 45.0 * ((mean_residual / cap - 0.5) * 2.0).min(1.0);
        }
        if progress > 0.7 && item_size < 30 {
            score += 80.0;
        }
        if progress > 0.85 && open_bins_count > 3 {
            score += 30.0 * progress;
        }
        // New bins are wasteful when an existing bin would close exactly.
        if post_residual == 0 && fitting_bins_count >= 1 {
            score += 400.0;
        }
        // Never open a new bin when the item nearly fills some existing bin.
        if fitting_bins_count >= 1 && pr > 0.0 && pr < 0.12 * cap {
            score += 120.0 * (1.0 - pr / (0.12 * cap));
        }
        // Forbid new bins when a perfect closure exists late in stream.
        if post_residual == 0 && progress > 0.7 {
            score += 150.0 * progress;
        }
        // Never open a new bin when an existing bin leaves residual
        // exactly equal to the next item (future closure preserved).
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual == next_item_size {
            score += 220.0;
        }
        // New bins forbidden when the item exactly matches a mean-residual bin.
        if fitting_bins_count >= 1 && (bin_residual as f64 - item_f) < 0.15 * cap
            && pr > 0.0 && pr < item_f * 2.0 {
            score += 70.0;
        }
        // Avoid opening bins for items that fit the mean residual well.
        if fitting_bins_count >= 1 && mean_residual >= item_f
            && (mean_residual - item_f) < 0.10 * cap {
            score += 90.0 * (1.0 - (mean_residual - item_f) / (0.10 * cap));
        }
        // Late stream — strongly discourage any new bin.
        if progress > 0.75 {
            score += 60.0 * progress;
        }
        // NEW: never open a bin for an item that fits some bin with <20% waste.
        if fitting_bins_count >= 1 && pr > 0.0 && pr < 0.20 * item_f {
            score += 200.0;
        }
        // NEW: allow new bins only for large items when all fits are terrible.
        if fitting_bins_count >= 1 && pr >= item_f {
            let waste = pr - item_f;
            score += 40.0 * (waste / cap).min(1.0);
        }
        // NEW: discourage new bins when many bins are already open.
        if open_bins_count > 3 {
            score += 25.0 * ((open_bins_count - 3) as f64).min(8.0);
        }
    }

    // Reward exact closure of an existing bin.
    if post_residual == 0 && bin_residual != bin_capacity && fitting_bins_count >= 1 {
        score -= 60.0 * (1.0 - item_ratio);
    }

    // Endgame consolidation.
    if progress > 0.9 && pr > 0.0 {
        score -= 30.0 * (1.0 - pr / cap) * progress;
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: leftover exactly fits the next item -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual > next_item_size {
            // Next item fits too: reward proportionally to how close to a second perfect fill.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.5 * slack.min(40.0);
        } else {
            // Next item won't fit: penalize dead space, worse when residual is small (unusable).
            let dead = (next_item_size - post_residual) as f64;
            score += 0.6 * dead;
            if post_residual < 10 {
                score += 25.0; // tiny unusable sliver
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Prefer bins tighter than the mean residual (well-filled bins first).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Penalize the brand-new empty bin unless nothing decent fits among open bins.
    if bin_residual == bin_capacity {
