pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream processed (dynamic time horizon).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core best-fit flavor: reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 6.0 * (1.0 - t);
        // Extra reward if next item fills it almost exactly.
        let chain_tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 8.0 * (1.0 - chain_tight);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use: penalize, more so early on.
        score += 4.0 + 4.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Many fitting bins: slight penalty for picking a mediocre one, pushing
    // toward the tightest fit via the base term.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Penalize dumping small items into bins with large residuals when the
    // mean residual is high (fragmentation risk); encourage consolidation.
    let frag = (bin_residual as f64 - mean_residual).max(0.0);
    score += 0.05 * frag * (1.0 - t);

    // New-bin candidate handling: opening a bin is attractive when few bins fit
    // the item or the stream is early; it is unattractive when a good fit exists.
    if bin_residual == bin_capacity {
        let early = 1.0 - t;
        if fitting_bins_count == 0 {
            score -= 20.0; // must open
        } else if fitting_bins_count == 1 {
            score += 8.0;  // keep using the last-chance bin instead
        } else {
            score += 6.0 + 6.0 * t - 4.0 * early; // prefer open bins, more so late
        }
        // If open bins are already quite full on average, a new bin is fine.
        if mean_residual < 25.0 {
            score -= 5.0;
        }
    }

    // Mild late-stream pressure to close bins out completely.
    score -= 3.0 * t * tightness;

    score
}

