    if pr >= item_f && item_size > 0 && (pr % item_size) == 0 && pr < cap {
        score -= 20.0 * (pr / item_f).min(4.0);
    }

    // Reward bins whose residual equals the current item size exactly.
    if post_residual == 0 && bin_residual != bin_capacity && fitting_bins_count >= 1 {
        score -= 60.0 * (1.0 - item_ratio);
    }

    // Anti-fragmentation: penalize residuals no plausible future item can pair with.
    if next_item_size > 0 && pr > 0.0 && pr < cap {
        let next = next_item_size as f64;
        let pairable = pr >= next || pr >= item_f || (pr + next) as u32 <= bin_capacity;
        if !pairable {
            score += 35.0 * (1.0 - pr / cap);
        }
    }

    // NEW: dead-space ratio penalty — the diagnosed weakness. Penalize bins whose
    // post-residual is a small, hard-to-fill sliver relative to the next item.
    if next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        let dead_ratio = 1.0 - pr / next_item_size as f64;
        score += 50.0 * dead_ratio * dead_ratio * (0.5 + progress);
    }

    // NEW: reward placements that keep the residual a multiple of common item
    // granularity, improving future divisibility of space.
    if pr > 0.0 && item_size > 1 && (pr % 2) == 0 && item_size % 2 == 0 {
        score -= 8.0;
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 bins group residuals into
    // "usable classes". Residuals in [0..10) are nearly dead space.
    let post_class = (post_residual / 10).min(10) as f64;
    let post_mod = (post_residual % 10) as f64;

    // Reward residuals that fall into high-utility classes (>= 20 remaining).
    score -= 6.0 * post_class;

    // Penalize sub-10 dead space super-linearly (fractional waste).
    if post_residual < 10 {
        score += 25.0 * (10.0 - post_mod) / 10.0;
    }

    // Perfect or near-perfect fits are gold.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // Extra reward if the next item's class aligns (divisibility harmony).
        if post_residual % next_item_size.max(1) == 0 {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here: mild penalty proportional to wasted lookahead.
        score += 4.0 * (next_item_size.min(post_residual + 30) as f64) / 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if mean residual across open bins is tiny (all bins packed),
        // opening a new bin is fine.
        if mean_residual < 12.0 {
            score -= 25.0;
        }
        // Early in the stream, prefer consolidating into fewer bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Mild tie-break: prefer bins with lower residual already (tighter packing).
    score += 0.05 * (bin_residual as f64 - post_residual as f64);

    // Coupling with mean residual: placing into a bin far below mean residual
    // balances the pool.
    score -= 0.1 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let item_ratio = item_size as f64 / cap;
    let item_f = item_size as f64;

    // Perfect fill: bin closes exactly.
    if post_residual == 0 {
        score -= 1150.0;
    }

    // Dead-space avoidance with graded penalties.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 420.0;
        } else if post_residual < 20 {
            score += 130.0;
        } else if post_residual < 35 {
            score += 32.0;
        } else if post_residual < 50 {
            score += 6.0;
        }
        let tight = 1.0 - (pr / cap);
        score -= 16.0 * tight * tight;
        if pr < 0.25 * cap {
            let r = pr / cap;
            score += 145.0 * r * (1.0 - 4.0 * r) * (1.0 - r) + 25.0 * r * r;
        }
    }

    // Two-step lookahead with chain planning.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 980.0;
        } else if post_residual > next_item_size {
            let gap = (pr - nxt);
            score -= 360.0 * (1.0 - gap / cap);
            if nxt > 0.5 * cap && fitting_bins_count <= 2 {
                score -= 150.0 * (nxt / cap);
            }
            if pr >= 2.0 * nxt && pr < cap {
                score -= 55.0 * (1.0 - pr / cap);
            }
            if pr >= 3.0 * nxt {
                score -= 35.0 * (nxt / cap);
            }
            if pr - nxt >= item_f {
                score -= 42.0 * item_ratio;
            }
            if pr >= nxt + item_f {
                score -= 22.0 * (1.0 - ((pr - nxt - item_f) / cap).min(1.0));
            }
            // Exact two-item drain.
            if (pr - nxt - item_f).abs() < 1.0 && pr >= nxt + item_f {
                score -= 85.0;
            }
            // Divisibility chain.
            if nxt > 0.0 && (post_residual % next_item_size) == 0 && pr < cap {
                score -= 30.0 * (pr / nxt).min(4.0);
            }
            // Triple chain with identical next items.
            if pr >= 2.0 * nxt && nxt > item_f {
                score -= 20.0 * (nxt / cap);
            }
            // Residual remainder matches current item size class.
            let rem = pr - nxt;
            if rem >= item_f && rem < item_f * 2.5 {
                score -= 18.0 * (1.0 - rem / (2.5 * item_f).max(1.0));
            }
            // Chain depth reward.
            if nxt > 0.0 && pr < cap {
                let depth = (pr / nxt).floor().min(6.0);
                if depth >= 2.0 {
                    score -= 12.0 * depth * (1.0 - item_ratio);
                }
            }
            // Two-item lookahead window.
            if pr >= nxt + item_f && (pr - nxt - item_f) < item_f * 3.0 {
                score -= 14.0 * (1.0 - (pr - nxt - item_f) / (3.0 * item_f).max(1.0));
            }
            // NEW: residual after placing next item still hosts the current item again.
            if pr >= nxt + item_f && (pr - nxt) % item_size.max(1) == 0 {
                score -= 26.0 * ((pr - nxt) / item_f).min(3.0);
            }
        } else {
            score += 0.65 * pr;
            if pr > 0.0 {
                let q = pr / nxt;
                score += 100.0 * q * (1.0 - q) + 65.0 * (1.0 - q);
                score += 45.0 * q * (nxt / cap);
            }
        }
        // Near-miss residual penalty (widened).
        if pr > 0.0 {
            let miss = (pr - nxt).abs();
            if miss > 0.0 && miss < 0.10 * cap {
                score += 60.0 * (1.0 - miss / (0.10 * cap));
            }
        }
        if bin_residual == bin_capacity && next_item_size == item_size {
            score -= 40.0;
        }
        // Harmonic distance coupling.
        if pr > 0.0 && pr != nxt {
            let dist = (pr - nxt).abs() / cap;
            score += 18.0 * dist * (1.0 - dist);
        }
        // Anti-fragmentation: residual unusable by current or next item.
        if pr > 0.0 && pr < cap {
            let pairable = pr >= nxt || pr >= item_f || (pr + nxt) as u32 <= bin_capacity;
            if !pairable {
                score += 35.0 * (1.0 - pr / cap);
            }
        }
    }

    // Tightness reward with concave saturation.
    let tightness = item_f / (bin_residual.max(1) as f64);
    score -= 10.0 * (1.0 - (-2.0 * tightness).exp());

    // Waste-ratio coupling, non-linear.
    let post_ratio = pr / cap;
    score += 70.0 * item_ratio * post_ratio * (1.0 + 0.5 * post_ratio);

    // Residual positioning vs mean.
    score += 0.38 * (pr - mean_residual).max(0.0);
    score -= 0.16 * (mean_residual - pr).max(0.0);
    if pr >= mean_residual && pr > 0.0 {
        score -= 32.0 * ((pr - mean_residual) / cap).min(0.25);
    }

    // Mid-stream sliver penalty when many bins are open.
    if open_bins_count > 4 && pr > 0.0 && pr < 0.3 * cap {
        let frac = pr / cap;
        score += 55.0 * frac * (1.0 - frac) * (open_bins_count as f64 / 10.0).min(1.0);
    }

    // Self-sustaining chains of identical items.
    if pr >= item_f && item_size > 0 && (pr % item_size) == 0 && pr < cap {
        score -= 20.0 * (pr / item_f).min(4.0);
    }

    // Last-chance pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Open-bin pressure, stronger late.
    score += 2.6 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let slack = mean_residual / cap;
        score += 128.0 + 195.0 * progress + 165.0 * slack.max(0.0);

        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 75.0;
        }
        if item_ratio > 0.6 {
            score -= 58.0;
        }
        if fitting_bins_count <= 2 && item_ratio > 0.45 {
            score -= 36.0 * item_ratio;
        }
        if pr > 0.0 && pr < 0.2 * cap && fitting_bins_count <= 3 {
            score -= 100.0;
        }
        if open_bins_count == 0 {
            score -= 42.0;
        }
        if item_ratio < 0.2 && progress > 0.5 {
            score += 48.0 * (1.0 - item_ratio * 5.0);
        }
        if next_item_size > 0 && next_item_size as f64 > 0.7 * cap && fitting_bins_count == 0 {
            score -= 60.0;
        }
        if mean_residual > 0.35 * cap && item_ratio < 0.5 {
            score += 55.0 * (mean_residual / cap - 0.35).min(0.4);
        }
        if progress < 0.2 && open_bins_count < 4 {
            score += 25.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual > 0.5 * cap {
            score += 45.0 * ((mean_residual / cap - 0.5) * 2.0).min(1.0);
        }
        if progress > 0.7 && item_size < 30 {
            score += 80.0;
        }
        if progress > 0.85 && open_bins_count > 3 {
            score += 30.0 * progress;
        }
        // New bins are wasteful when an existing bin would close exactly.
        if post_residual == 0 && fitting_bins_count >= 1 {
            score += 400.0;
        }
        // Never open a new bin when the item nearly fills some existing bin.
        if fitting_bins_count >= 1 && pr > 0.0 && pr < 0.12 * cap {
            score += 120.0 * (1.0 - pr / (0.12 * cap));
        }
        // Forbid new bins when a perfect closure exists late in stream.
        if post_residual == 0 && progress > 0.7 {
            score += 150.0 * progress;
        }
        // Preserve future closure: residual == next item.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual == next_item_size {
            score += 220.0;
        }
        // New bins forbidden when the item exactly matches a mean-residual bin.
        if fitting_bins_count >= 1 && (bin_residual as f64 - item_f) < 0.15 * cap
            && pr > 0.0 && pr < item_f * 2.0 {
            score += 70.0;
        }
        // Avoid opening bins for items that fit the mean residual well.
        if fitting_bins_count >= 1 && mean_residual >= item_f
            && (mean_residual - item_f) < 0.10 * cap {
            score += 90.0 * (1.0 - (mean_residual - item_f) / (0.10 * cap));
        }
        // Late stream — strongly discourage any new bin.
        if progress > 0.75 {
            score += 60.0 * progress;
        }
        // Early stream with few bins — allow fresh bins for big items.
        if progress < 0.3 && item_ratio > 0.5 && open_bins_count < 3 {
            score -= 55.0 * item_ratio;
        }
        // NEW: discourage new bins when item would leave a residual matching
        // the next item exactly in an existing bin (lookahead closure).
        if fitting_bins_count >= 1 && next_item_size > 0
            && (bin_residual as u32).saturating_sub(item_size as u32) == next_item_size {
            score += 140.0;
        }
        // NEW: new bins acceptable only if the fresh residual can host the next item.
        if next_item_size > 0 && next_item_size as f64 > cap - item_f {
            score -= 35.0;
        }
    }

    // Reward exact closure of an existing bin.
    if post_residual == 0 && bin_residual != bin_capacity && fitting_bins_count >= 1 {
        score -= 60.0 * (1.0 - item_ratio);
    }

    // Endgame consolidation.
    if progress > 0.9 && pr > 0.0 {
        score -= 30.0 * (1.0 - pr / cap) * progress;
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100 range),
    // but especially if it falls into a hard-to-fill band (1..=15).
    if post_residual > 0 && post_residual <= 15 {
        score += 30.0 + (15 - post_residual) as f64 * 2.0;
    } else if post_residual > 15 && post_residual <= 30 {
        // Medium gaps: mildly penalized, they can still fit small-to-medium items.
        score += 6.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Coupling with lookahead: if the next item fits exactly into the post_residual,
    // this placement is excellent — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; if the gap is dead-small, penalize more.
        if post_residual < next_item_size && post_residual <= 20 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones
    // (avoid proliferation of bins with scattered residual capacity).
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 3.0 * bin_pressure;
    } else {
        // New-bin candidate: penalize it more as open bin count grows,
        // but give it a bonus if its residual would be perfectly usable (full capacity).
        score += 8.0 + 2.0 * bin_pressure;
    }

    // Prefer bins whose residual is below the mean (i.e., fuller bins),
    // consolidating capacity into few bins.
    let mean_gap = mean_residual - bin_residual as f64;
    score += 0.15 * mean_gap;

    // Slight stream-progression term: late in the stream, be more conservative
    // about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

