        score += 128.0 + 195.0 * progress + 165.0 * slack.max(0.0);

        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 75.0;
        }
        if item_ratio > 0.6 {
            score -= 58.0;
        }
        if fitting_bins_count <= 2 && item_ratio > 0.45 {
            score -= 36.0 * item_ratio;
        }
        if pr > 0.0 && pr < 0.2 * cap && fitting_bins_count <= 3 {
            score -= 100.0;
        }
        if progress > 0.85 && open_bins_count > 3 {
            score += 30.0 * progress;
        }
        if open_bins_count == 0 {
            score -= 42.0;
        }
        if item_ratio < 0.2 && progress > 0.5 {
            score += 48.0 * (1.0 - item_ratio * 5.0);
        }
        if next_item_size > 0 && next_item_size as f64 > 0.7 * cap && fitting_bins_count == 0 {
            score -= 60.0;
        }
        if mean_residual > 0.35 * cap && item_ratio < 0.5 {
            score += 55.0 * (mean_residual / cap - 0.35).min(0.4);
        }
        if progress < 0.2 && open_bins_count < 4 {
            score += 25.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual > 0.5 * cap {
            score += 45.0 * ((mean_residual / cap - 0.5) * 2.0).min(1.0);
        }
        // Opening a fresh bin is wasteful when an existing bin would close exactly.
        if post_residual == 0 && fitting_bins_count >= 1 {
            score += 400.0;
        }
        // Never open a new bin when the item nearly fills some existing bin.
        if fitting_bins_count >= 1 && pr > 0.0 && pr < 0.12 * cap {
            score += 120.0 * (1.0 - pr / (0.12 * cap));
        }
        // Forbid new bins when a perfect closure exists late in stream.
        if post_residual == 0 && progress > 0.7 {
            score += 150.0 * progress;
        }
        // New: discourage fresh bins when some open bin can absorb the item
        // with residual still at or above the mean (healthy leftover).
        if fitting_bins_count >= 1 && pr >= mean_residual {
            score += 40.0 * (pr / cap);
        }
    }

    // Harmonic coupling: prefer residuals near a future-fit size.
    if next_item_size > 0 && pr > 0.0 && pr != next_item_size as f64 {
        let dist = (pr - next_item_size as f64).abs() / cap;
        score += 18.0 * dist * (1.0 - dist);
    }

    // Endgame consolidation.
    if progress > 0.9 && pr > 0.0 {
        score -= 30.0 * (1.0 - pr / cap) * progress;
    }

    // Mid-stream consolidation: penalize odd slivers when many bins are open.
    if open_bins_count > 4 && pr > 0.0 && pr < 0.3 * cap {
        let frac = pr / cap;
        score += 55.0 * frac * (1.0 - frac) * (open_bins_count as f64 / 10.0).min(1.0);
    }

    // Self-sustaining chains of identical items.
    if pr >= item_f && item_size > 0 && (pr % item_size) == 0 && pr < cap {
        score -= 20.0 * (pr / item_f).min(4.0);
    }

    // Reward bins whose residual equals the current item size exactly.
    if post_residual == 0 && bin_residual != bin_capacity && fitting_bins_count >= 1 {
        score -= 60.0 * (1.0 - item_ratio);
    }

    // Anti-fragmentation: penalize residuals no plausible future item can pair with.
    if next_item_size > 0 && pr > 0.0 && pr < cap {
        let next = next_item_size as f64;
        let pairable = pr >= next || pr >= item_f || (pr + next) as u32 <= bin_capacity;
        if !pairable {
            score += 35.0 * (1.0 - pr / cap);
        }
    }

    // New: dead-space ratio coupling — penalize placements leaving residuals
    // that are awkwardly between common item sizes, scaled by how much of
    // the stream remains.
    if pr > 0.0 && pr < cap && progress < 0.8 {
        let r = pr / cap;
        let awkward = 4.0 * r * (1.0 - r); // peaks at r = 0.5
        score += 14.0 * awkward * (1.0 - progress) * (1.0 - item_ratio);
    }

    // New: reward placements that leave residual exactly equal to a small
    // multiple of the mean residual (likely to match future demand).
    if pr > 0.0 && mean_residual > 0.0 {
        let k = pr / mean_residual;
        if (k - k.round()).abs() < 0.08 && k >= 1.0 && k <= 3.0 {
            score -= 22.0 * (1.0 - (k - k.round()).abs() / 0.08);
        }
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = pr + 40.0 * pr_norm * pr_norm * (1.0 - pr_norm);

    // Non-linear polynomial coupling with stream progress:
    // early stream: tolerate loose fits; late stream: penalize wasted space quadratically
    let progress_coupling = 1.0 + 3.0 * progress * progress;
    score *= progress_coupling;

    // Smooth interaction: post_residual vs mean residual divergence
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev * (0.5 + 0.5 * progress);

    // Last-chance bonus: smooth sigmoid-like reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pr_norm * pr_norm);
    }

    // Lookahead coupling: reward if next item fits into post-residual (smooth, not piecewise)
    if next_item_size > 0 {
        let fits = (next_item_size as f64 - pr).max(0.0);
        let fit_frac = 1.0 - fits / cap;
        score -= 20.0 * fit_frac * fit_frac * (1.0 - progress);
    }

    // Slight penalty for spreading across too many bins late in the stream
    score += 2.0 * open_bins_count as f64 * progress * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
