        } else if post_residual < 20 {
            score += 130.0;
        } else if post_residual < 35 {
            score += 32.0;
        } else if post_residual < 50 {
            score += 6.0;
        }
        let tight = 1.0 - (pr / cap);
        score -= 16.0 * tight * tight;
    }

    // Quartic dead-space penalty in the awkward zone.
    if pr > 0.0 && pr < 0.25 * cap {
        let r = pr / cap;
        score += 145.0 * r * (1.0 - 4.0 * r) * (1.0 - r) + 25.0 * r * r;
    }

