        }
        // Late stream — strongly discourage any new bin.
        if progress > 0.75 {
            score += 60.0 * progress;
        }
        // Early stream with few bins — allow fresh bins for big items.
        if progress < 0.3 && item_ratio > 0.5 && open_bins_count < 3 {
            score -= 55.0 * item_ratio;
        }
    }

    // Reward exact closure of an existing bin.
    if post_residual == 0 && bin_residual != bin_capacity && fitting_bins_count >= 1 {
        score -= 60.0 * (1.0 - item_ratio);
    }

    // Endgame consolidation.
    if progress > 0.9 && pr > 0.0 {
        score -= 30.0 * (1.0 - pr / cap) * progress;
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction slot does it land in?
    let pr = post_residual;
    let class = pr / 10; // integer division: 0..10 residual decile
    let frac = (pr as f64) / cap;

    // Reward near-perfect fits (harmonic class 0 = almost full bin)
    if class == 0 {
        score -= 25.0;
    } else if class == 1 {
        score -= 12.0;
    } else if class == 2 {
        score -= 5.0;
    }

    // Penalize mid-range dead space (classes 4..6 are the least reusable)
    if class >= 4 && class <= 6 {
        score += 8.0 + 2.0 * (class as f64 - 4.5).abs();
    }

    // Modulo arithmetic: residuals divisible by common item sizes are reusable
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 20 == 0 && pr > 0 {
        score -= 4.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        if slack == 0.0 {
            score -= 30.0;
        } else if slack <= 10.0 {
            score -= 18.0 - slack;
        } else {
            score -= 4.0;
        }
    }
    // Penalize if next item almost fits but not quite (dead space trap)
    if next_item_size > pr && next_item_size - pr <= 5 && pr > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: keep it slightly unattractive unless all else is bad
    if bin_residual == bin_capacity {
        score = cap - 15.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    // Stream progression: later in stream, prefer tighter packing (reward low residuals more)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - frac) * 10.0 * progress;

    // Mean residual coupling: if open bins are generally loose, penalize adding to loose bins
    if (mean_residual - frac * cap).abs() < 5.0 && pr > 30 {
        score += 5.0;
    }

    score
}

