            score -= 25.0 * (1.0 - gap / 5.0); // near-perfect chain placement
        } else if pr >= nx {
            score -= 5.0 * (nx / pr); // mild reward if next item still fits
        } else {
            // next item won't fit: penalize dead space, worse for small leftovers
            score += 8.0 * (1.0 - pr / 100.0);
        }
    } else {
        // last item: reward tightest fill
        score -= 20.0 * (item_size as f64 / bin_residual as f64);
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable.
    let tightness = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score += 15.0 * tightness;

    // Last-chance bonus: only bin that fits -> strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when no good chain exists and
    // placing here would leave a large awkward gap.
    if bin_residual == bin_capacity {
        let awkward = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs()
        } else {
            0.0
        };
        if open_bins_count == 0 {
            score -= 50.0; // must open first bin
        } else if awkward > 30.0 && next_item_size > 0 && post_residual < next_item_size {
            score -= 12.0; // current bins can't chain well -> open fresh bin
        } else {
            score += 20.0; // keep filling existing bins when reasonable
        }
    }

