    if open_bins_count > 4 && pr > 0.0 && pr < 0.3 * cap {
        let frac = pr / cap;
        score += 55.0 * frac * (1.0 - frac) * (open_bins_count as f64 / 10.0).min(1.0);
    }

    // Self-sustaining chains of identical items.
    if item_size > 0 && pr >= item_f && (pr as u32 % item_size) == 0 && pr < cap {
        score -= 20.0 * (pr / item_f).min(4.0);
    }

    // Reward exact-emptiness placements even when next_item differs.
    if post_residual == 0 && bin_residual != bin_capacity && fitting_bins_count >= 1 {
        score -= 60.0 * (1.0 - item_ratio);
    }

    // Anti-fragmentation: penalize residuals no plausible future item can pair with.
    if next_item_size > 0 && pr > 0.0 && pr < cap {
        let next = next_item_size as f64;
        let pairable = pr >= next || pr >= item_f || (pr + next) as u32 <= bin_capacity;
        if !pairable {
            score += 35.0 * (1.0 - pr / cap);
        }
    }

    // Endgame consolidation.
    if progress > 0.9 && pr > 0.0 {
        score -= 30.0 * (1.0 - pr / cap) * progress;
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let slack = mean_residual / cap;
        score += 128.0 + 195.0 * progress + 165.0 * slack.max(0.0);

        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 75.0;
        }
        if item_ratio > 0.6 {
            score -= 58.0;
        }
        if fitting_bins_count <= 2 && item_ratio > 0.45 {
            score -= 36.0 * item_ratio;
        }
        if pr > 0.0 && pr < 0.2 * cap && fitting_bins_count <= 3 {
            score -= 100.0;
        }
        if progress > 0.85 && open_bins_count > 3 {
            score += 30.0 * progress;
        }
        if open_bins_count == 0 {
            score -= 42.0;
        }
        if item_ratio < 0.2 && progress > 0.5 {
            score += 48.0 * (1.0 - item_ratio * 5.0);
        }
        if next_item_size > 0 && next_item_size as f64 > 0.7 * cap && fitting_bins_count == 0 {
            score -= 60.0;
        }
        if mean_residual > 0.35 * cap && item_ratio < 0.5 {
            score += 55.0 * (mean_residual / cap - 0.35).min(0.4);
        }
        if progress < 0.2 && open_bins_count < 4 {
            score += 25.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual > 0.5 * cap {
            score += 45.0 * ((mean_residual / cap - 0.5) * 2.0).min(1.0);
        }
        // Never open a new bin when an existing bin would close exactly.
        if post_residual == 0 && fitting_bins_count >= 1 {
            score += 400.0;
        }
        // Never open a new bin when the item nearly fills some existing bin
        // (slivers are the dominant waste mode).
        if fitting_bins_count >= 1 && pr > 0.0 && pr < 0.12 * cap {
            score += 120.0 * (1.0 - pr / (0.12 * cap));
        }
        // Forbid new bins when a perfect closure exists late in stream.
        if post_residual == 0 && progress > 0.7 {
            score += 150.0 * progress;
        }
        // Resist opening new bins when existing residuals can host next item too.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let next = next_item_size as f64;
            if pr >= next {
                score += 45.0 * progress;
            }
        }
        // Resist new bins when some existing residual can host BOTH current
        // and next item (combined lookahead compaction).
        if next_item_size > 0 && fitting_bins_count >= 1 && (item_f + next_item_size as f64) <= cap {
            score += 30.0 * (1.0 - (item_f + next_item_size as f64) / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = item_size as f64 / cap;
    let post_frac = post / cap;

    // Base: prefer small post residual, but non-linearly penalize tiny dead space
    let mut score = post;

    // Smooth non-linear coupling: reward tight fits more strongly as stream progresses
    let tightness = 1.0 - post_frac;
    score -= 14.0 * tightness * tightness * (0.6 + 0.8 * progress);

    // Penalize unusable dead space (post_residual too small for typical future items)
    // Smooth ramp: dead space penalty grows when post_residual < ~12
    let dead = (12.0 - post).max(0.0) / 12.0;
    score += 20.0 * dead * dead * (1.2 - 0.5 * progress);

    // Lookahead: reward if next item fits into post residual (smooth interaction)
    if next_item_size > 0 {
        let next_fits = 1.0 - ((next_item_size as f64 - post) / cap).max(0.0).min(1.0);
        score -= 8.0 * next_fits * fit_frac;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 15.0 * progress;
    }

    // Mild penalty for opening new bins when many bins are open with roomy residuals
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 6.0 + 0.6 * open_bins_count as f64 * (1.0 - progress) + 4.0 * (mean_residual / cap).max(0.0);
    }

    // Small global regularization coupling progress and fit fraction
    score += 3.0 * (1.0 - fit_frac) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
