    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" is the leftover space?
    // Class residuals that are multiples of common item sizes (10, 20, 25, 50) are reusable.
    let r = post_residual;
    let harmonic_bonus = if r == 0 {
        60.0 // perfect fit, strongly reward
    } else if r % 50 == 0 {
        30.0
    } else if r % 25 == 0 {
        22.0
    } else if r % 20 == 0 {
        18.0
    } else if r % 10 == 0 {
        12.0
    } else if r % 5 == 0 {
        6.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize tiny dead space that nothing (>=1) can use productively
    if r > 0 && r < 10 {
        score += 25.0;
    }

    // Lookahead coupling: does post_residual fit the next item exactly / well?
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 45.0; // perfect chained fit
        } else if next_item_size <= r {
            let slack = (r - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: mild penalty scaled by how far off
            score += ((next_item_size - r).min(30)) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual here.
    if bin_residual == bin_capacity {
        // Prefer new bin when current open bins are crowded with small residuals
        // or when this item is large and would fragment bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0;
        if item_size >= 50 {
            score -= 10.0; // big items better in fresh bins
        }
        if mean_residual < item_size as f64 * 1.2 {
            score -= 12.0 * (1.0 - progress * 0.5);
        }
        // Penalize opening new bins too liberally when many bins already fit
        if fitting_bins_count > 3 {
            score += 20.0;
        }
    } else {
        // Favor tight fits: reward small post residual relative to capacity
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

        // Prefer bins whose residual is close to the mean (keeps bin states uniform)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;

        // Early stream: consolidate; late stream: allow more spreading
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count > 4 && progress < 0.5 {
            score += 3.0;
        }
    }

    // Integer-division threshold: residual buckets of 10 get graded reusability
    let bucket = r / 10;
    score -= bucket as f64 * 1.5;

    score
}

