    // Endgame consolidation.
    if progress > 0.9 && pr > 0.0 {
        score -= 30.0 * (1.0 - pr / cap) * progress;
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for any plausible item
    // (sizes can be as small as 1) are wasted space; punish sharply.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 - 5.0 * post_residual as f64;
    }

    // Reward tight fits (small but still usable residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual closely matches the item (minimal overshoot).
    let overshoot = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 15.0 * overshoot;

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If the next item almost fits (small gap), mild penalty for stranding it.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 {
        score += 6.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize new-bin usage indirectly by penalizing bins less when count is high).
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score -= 10.0 * pressure * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make the empty bin attractive only when existing bins
    // would leave large dead space or the stream is early with few bins.
    if bin_residual == bin_capacity {
        let early = (step_index as f64 / (total_items.max(1) as f64)) < 0.15;
        if early && open_bins_count < 3 {
            score -= 8.0;
        } else {
            score += 20.0 + mean_residual * 0.05;
        }
    }

    score
}

