    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" the leftover space is.
    // Residuals in [0..=9] are near-perfect fits; [10..=19] excellent; large residuals waste capacity.
    let pr = post_residual as i64;
    let dead_penalty: f64 = if pr == 0 {
        -60.0 // perfect fill: strong reward
    } else if pr <= 5 {
        -30.0
    } else if pr <= 10 {
        -15.0
    } else if pr <= 19 {
        0.0
    } else if pr <= 30 {
        10.0
    } else if pr <= 50 {
        25.0
    } else {
        40.0
    };
    score += dead_penalty;

    // Modulo-10 harmonic class: leftover space that is a multiple of 10 is more
    // likely to be filled by future items (sizes drawn with 10-granularity often).
    if pr > 0 && pr % 10 == 0 {
        score -= 8.0;
    } else if pr > 0 && pr % 5 == 0 {
        score -= 4.0;
    }

    // Integer-division thresholds: pair post_residual with next_item_size.
    // Reward bins whose leftover can exactly host the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // lookahead chains perfectly
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 12.0;
            } else if slack <= 15 {
                score -= 5.0;
            }
        } else {
            // lookahead won't fit here: leftover may be stranded
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin offers a tight fit.
        // Penalize the new bin by the mean residual (if open bins have slack, prefer them),
        // but give it a floor so it beats catastrophically wasteful placements.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 0.15 * mean_residual + 10.0 * progress;
        // If the item exactly fills a fresh bin, opening is great.
        if item_size == bin_capacity {
            score -= 60.0;
