    // (i.e., a tight bin) is desirable; a loose bin above mean is wasteful.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Harmonic class of item size: large items (mod classes near capacity fractions)
    // should go into the emptiest bins.
    let item_class = item_size / 20; // 0..4 harmonic class
    score -= item_class as f64 * (bin_residual as f64 / bin_capacity as f64) * 6.0;

    score
