    // Mid-range awkward gaps (10..20) that few items can use.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: prefer spreading across fewer bins; discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 30.0 + 6.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mean residual coupling: if this bin's residual deviates badly from mean, penalize.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Early stream: be a bit more permissive about new bins to build good structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
