    let pr = post_residual as f64;

    // Perfect fit is golden: bin closes exactly.
    if post_residual == 0 {
        score -= 1150.0;
    }

    // Two-step lookahead with chain planning.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 950.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 340.0 * (1.0 - gap / cap);
            // Scarce placement opportunities: large next item with few hosts.
            if nxt > 0.5 * cap && fitting_bins_count <= 2 {
                score -= 140.0 * (nxt / cap);
            }
            // Multi-item chain planning: residual can host next plus more copies.
