            }
            // Divisible residual: future items tile it exactly.
            if (post_residual % next_item_size) == 0 && pr < cap {
                score -= 28.0 * (pr / nxt).min(4.0);
            }
        } else {
            // Dead space the next item cannot use.
            score += 0.6 * pr;
            if pr > 0.0 && pr < nxt {
