        let dist = (pr - next_item_size as f64).abs() / cap;
        score += 18.0 * dist * (1.0 - dist);
    }

    // Endgame consolidation.
    if progress > 0.9 && pr > 0.0 {
        score -= 30.0 * (1.0 - pr / cap) * progress;
    }

    // Mid-stream consolidation: penalize odd slivers when many bins are open.
    if open_bins_count > 4 && pr > 0.0 && pr < 0.3 * cap {
        let frac = pr / cap;
        score += 55.0 * frac * (1.0 - frac) * (open_bins_count as f64 / 10.0).min(1.0);
    }

    // Self-sustaining chains of identical items.
    if pr >= item_f && item_size > 0 && (pr % item_size) == 0 && pr < cap {
        score -= 20.0 * (pr / item_f).min(4.0);
    }

    // Reward bins whose residual equals the current item size exactly.
    if post_residual == 0 && bin_residual != bin_capacity && fitting_bins_count >= 1 {
        score -= 60.0 * (1.0 - item_ratio);
    }

    // Anti-fragmentation: penalize residuals no plausible future item can pair with.
    if next_item_size > 0 && pr > 0.0 && pr < cap {
        let next = next_item_size as f64;
        let pairable = pr >= next || pr >= item_f || (pr + next) as u32 <= bin_capacity;
        if !pairable {
            score += 35.0 * (1.0 - pr / cap);
        }
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by integer division into
    // "usable" harmonic bands. Residuals that can host common future item
    // sizes are valuable; tiny dead-space residuals are penalized.
    let cap = bin_capacity as f64;

    // --- Perfect fit: reward strongly ---
    if post_residual == 0 {
        score -= 1000.0;
    }

    // --- Harmonic class of post_residual via integer division thresholds ---
    // Class 0: post_residual == 0 (perfect)
    // Class 1: 0 < post <= 10  (dead space, useless for most items)
    // Class 2: 10 < post <= 25 (usable for small items)
    // Class 3: 25 < post <= 50 (half-bin, very reusable)
    // Class 4: post > 50       (large space, keep for big items)
    let harmonic_class: u32 = if post_residual == 0 {
        0
    } else if post_residual <= 10 {
        1
    } else if post_residual <= 25 {
        2
    } else if post_residual <= 50 {
        3
    } else {
        4
    };

    match harmonic_class {
        0 => { score -= 500.0; }
        1 => { score += 60.0; }      // dead space penalty
        2 => { score += 10.0; }      // mildly useful
        3 => { score -= 40.0; }      // half-bin is gold
        _ => { score -= 5.0; }       // large residual, keep flexible
    }

    // --- Modulo arithmetic: reward residuals that are multiples of common
    // item granularity (items often cluster on 5/10 boundaries) ---
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 7.0;
    }

    // --- Lookahead: if next item fits exactly in post_residual, big reward ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how snugly
            let snug = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - snug / cap);
        } else {
            // next item cannot use this residual: penalize wasted potential
            let waste = (next_item_size - post_residual).min(next_item_size) as f64;
            score += 20.0 * (waste / 100.0);
        }
    }

    // --- Tight fit reward: item almost fills the bin ---
    let fill_ratio = item_size as f64 / cap;
    if fill_ratio > 0.9 {
        score -= 80.0;
    } else if fill_ratio > 0.7 {
        score -= 30.0;
    }

    // --- Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible ---
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost. It should win only when no
        // open bin offers a decent fit. Base penalty grows with stream
        // progress (later, consolidating is better) and with many open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 170.0 + 60.0 * progress + 3.0 * open_bins_count as f64;

        // If the next item is huge, a fresh bin is attractive.
        if next_item_size >= 70 {
            score -= 40.0;
        }
        // If many bins fit the item already, opening new is less attractive.
        score += 12.0 * fitting_bins_count as f64;
        // Mean residual high => open bins have room; discourage new bin.
        score += mean_residual * 0.3;
    } else {
        // Existing bin: slight preference for bins with lower mean-relative
        // residual (i.e., prefer filling fuller bins first — best-fit flavor).
        let rel = if mean_residual > 0.0 { bin_residual as f64 / mean_residual } else { 1.0 };
        score -= 10.0 * (rel - 1.0); // lower residual than mean => bonus
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
