        // bin wastes the accumulated space — discourage harder.
        if fitting_bins_count >= 2 && mean_residual > 0.45 * cap {
            score += 40.0 * (mean_residual / cap - 0.45);
        }
        // NEW: opening a new bin is acceptable when the item is large and the
        // fresh residual exactly matches the next item (chain seeding).
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 45.0;
        }
    }

