    }

    // Reward exact closure of an existing bin.
    if post_residual == 0 && bin_residual != bin_capacity && fitting_bins_count >= 1 {
        score -= 60.0 * (1.0 - item_ratio);
    }

    // Endgame consolidation.
    if progress > 0.9 && pr > 0.0 {
        score -= 30.0 * (1.0 - pr / cap) * progress;
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone_max = 10.0f64;
    if post_residual > 0 && (post_residual as f64) <= dead_zone_max {
        score += (dead_zone_max - post_residual as f64 + 1.0) * 12.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 8.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize if next item cannot fit in post residual but could have fit with better packing.
    if next_item_size > post_residual && next_item_size > 0 && next_item_size <= bin_residual - item_size {
        // same thing; keep coupling mild
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open bins pressure: many open bins -> discourage spreading, encourage new-bin only when needed.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * (1.0 - progress));

    // New-bin candidate handling: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, reduced when open bins are scarce or residual is high.
        score = 55.0 + open_bins_count as f64 * 2.0 - mean_residual * 0.15;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative
        }
    }

    // Mild mean-residual coupling: prefer bins whose residual deviates less from mean (keeps pool uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
