        if item_ratio > 0.6 {
            score -= 58.0;
        }
        if fitting_bins_count <= 2 && item_ratio > 0.45 {
            score -= 36.0 * item_ratio;
        }
        if pr > 0.0 && pr < 0.2 * cap && fitting_bins_count <= 3 {
            score -= 100.0;
        }
        if progress > 0.85 && open_bins_count > 3 {
            score += 30.0 * progress;
        }
        if open_bins_count == 0 {
            score -= 42.0;
        }
        if item_ratio < 0.2 && progress > 0.5 {
            score += 48.0 * (1.0 - item_ratio * 5.0);
        }
        if next_item_size > 0 && next_item_size as f64 > 0.7 * cap && fitting_bins_count == 0 {
            score -= 60.0;
        }
        if mean_residual > 0.35 * cap && item_ratio < 0.5 {
            score += 55.0 * (mean_residual / cap - 0.35).min(0.4);
        }
        if progress < 0.2 && open_bins_count < 4 {
            score += 25.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual > 0.5 * cap {
            score += 45.0 * ((mean_residual / cap - 0.5) * 2.0).min(1.0);
        }
        // Opening a fresh bin is wasteful when an existing bin would close exactly.
        if post_residual == 0 && fitting_bins_count >= 1 {
            score += 400.0;
        }
        // Never open a new bin when the item nearly fills some existing bin.
        if fitting_bins_count >= 1 && pr > 0.0 && pr < 0.12 * cap {
            score += 120.0 * (1.0 - pr / (0.12 * cap));
        }
        // Forbid new bins when a perfect closure exists late in stream.
        if post_residual == 0 && progress > 0.7 {
            score += 150.0 * progress;
        }
        // NEW: forbid new bins when placing item leaves a residual that exactly
        // equals the next item size in some existing bin.
        if fitting_bins_count >= 1 && next_item_size > 0 && pr == next_item_size as f64 {
            score += 220.0;
        }
        // NEW: discourage new bins whose fresh residual cannot host the next item.
        if next_item_size > 0 && next_item_size as f64 > cap * 0.5 {
            score += 35.0 * (next_item_size as f64 / cap - 0.5) * 2.0;
        }
    }

    // Harmonic coupling: prefer residuals near a future-fit size.
    if next_item_size > 0 && pr > 0.0 && pr != next_item_size as f64 {
        let dist = (pr - next_item_size as f64).abs() / cap;
        score += 18.0 * dist * (1.0 - dist);
    }

    // Endgame consolidation.
    if progress > 0.9 && pr > 0.0 {
        score -= 30.0 * (1.0 - pr / cap) * progress;
    }

    // Mid-stream consolidation: penalize odd slivers when many bins are open.
    if open_bins_count > 4 && pr > 0.0 && pr < 0.3 * cap {
        let frac = pr / cap;
        score += 55.0 * frac * (1.0 - frac) * (open_bins_count as f64 / 10.0).min(1.0);
    }

    // Self-sustaining chains of identical items.
    if pr >= item_f && item_size > 0 && (pr % item_size) == 0 && pr < cap {
        score -= 20.0 * (pr / item_f).min(4.0);
    }

    // Reward bins whose residual equals the current item size exactly.
    if post_residual == 0 && bin_residual != bin_capacity && fitting_bins_count >= 1 {
        score -= 60.0 * (1.0 - item_ratio);
    }

    // Anti-fragmentation: penalize residuals no plausible future item can pair with.
    if next_item_size > 0 && pr > 0.0 && pr < cap {
        let next = next_item_size as f64;
        let pairable = pr >= next || pr >= item_f || (pr + next) as u32 <= bin_capacity;
        if !pairable {
            score += 35.0 * (1.0 - pr / cap);
        }
    }

    // NEW: residual-diversity guard — avoid leaving residuals clustered just
    // above the next item size (dead space of 1..small gap is the worst case).
    if next_item_size > 0 && pr > next_item_size as f64 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 && gap < 0.05 * cap {
            score += 40.0 * (1.0 - gap / (0.05 * cap));
        }
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score = post_residual as f64 * (1.0 + 0.35 * fit_ratio);

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small dead zones are reusable for
    // tiny items (1..=10); mid zones (11..=30) risk becoming dead space.
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        score -= 8.0; // reusable micro-residual class
    } else if pr > 10 && pr <= 30 {
        score += 12.0; // awkward class: too small for most items
    } else if pr > 30 && pr <= 50 {
        score -= 3.0; // still broadly useful
    }

    // Integer-division thresholds: residual divisible by common item sizes
    // is more likely to be exactly consumed later.
    if pr >= 10 && (pr % 10 == 0) {
        score -= 4.0;
    }
    if pr >= 25 && (pr % 25 == 0) {
        score -= 2.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0 + (next_item_size as f64 / pr.max(1) as f64) * 8.0;
        } else {
            score += 6.0; // this bin becomes dead for the next item
            // penalize more if residual lands in awkward class
            if pr > 0 && pr < next_item_size && pr < 20 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly
    // (item leaves large residual or no bin fits well).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        // Default modest score: an empty bin has residual 100.
        score = 100.0 - 0.5 * pressure;
        if fitting_bins_count == 0 {
            score -= 60.0; // forced new bin
        } else {
            // discourage opening new bin when a decent fit exists
            let best_possible = (bin_capacity - item_size) as f64;
            if best_possible < 20.0 {
                score += 40.0;
            }
            if next_item_size > 0 && next_item_size > item_size && next_item_size > mean_residual {
                score -= 20.0; // next item is big; keep open bins flexible anyway
                score += 10.0;
            }
        }
        // Early in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Mild preference to fill bins with larger mean residual (balance load).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
