pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item are pure waste; penalize them heavily.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 60.0 - (post_residual as f64) * 2.0;
    }

    // Small-but-usable residuals are also risky: they can only host tiny
    // items, so apply a graded penalty in the awkward band.
    if post_residual >= dead_threshold && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (low post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than spreading; penalize new-bin usage.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement is excellent; reward it.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }
    // If next item would be blocked by this placement's residual, mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate handling: a fresh bin is only attractive when no
    // open bin offers a decent fit (large residual waste elsewhere).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 45.0 + pressure * 0.5;
        // Reward opening a bin that will snugly host the next item too.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            let pair_waste = bin_capacity - item_size - next_item_size;
            if pair_waste < 10 {
                score -= 30.0;
            }
        }
        // If only this candidate fits, opening a bin is necessary.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mean-residual coupling: when average residual across bins is already
    // small, avoid scattering; prefer bins below mean residual (tighter).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
