                40.0 // perfect 2-step fill
            } else {
                40.0 * (1.0 - gap / 50.0).max(0.0)
            };
            score -= match_reward;
        } else {
            // Next item cannot fit: penalize wasted residual relative to next size.
            score += 0.15 * (nxt - post);
        }
    }

    // ---- Mean-residual coupling ----
    // Prefer bins whose post residual stays near the mean (keeps flexibility),
    // penalize bins that would become outliers (dead space).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.25 * dev;

    // ---- Last-chance bin: strongly prefer using it ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin: mild penalty so it is chosen only when no open bin
        // offers a decent fit (i.e., when all others score worse).
        score += 8.0 + 20.0 * progress;
        // If item nearly fills a fresh bin, opening is attractive.
        if item_size as f64 >= 0.7 * bin_capacity as f64 {
            score -= 25.0;
