        if !pairable {
            score += 35.0 * (1.0 - pr / cap);
        }
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: waste term, quadratic penalty on unusable dead space
    let mut score = norm_pr * norm_pr * 60.0 + pr * 0.5;

    // Smooth polynomial coupling of post_residual with stream progress
    let s = t * t * (3.0 - 2.0 * t); // smoothstep, no piecewise constants
    score += norm_pr * (1.0 - s) * 20.0;      // early: tolerate slack
    score -= norm_pr * s * 15.0;              // late: prefer tight fits

    // Cubic interaction: large residuals become increasingly bad as stream progresses
    score += s * norm_pr * norm_pr * norm_pr * 40.0;

    // Reward near-perfect fits smoothly
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * tightness * 25.0;

    // Lookahead: bonus if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 12.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Pressure from many open bins: favor filling existing bins
    let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).powi(2);
    score -= pressure * 10.0 * (1.0 - norm_pr);

    // Mean residual alignment: prefer bins close to the mean residual (smooth)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 15.0;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - s) + 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let item_ratio = item_size as f64 / cap;
    let item_f = item_size as f64;

    // Perfect fit: close the bin decisively.
    if post_residual == 0 {
        score -= 1150.0;
    }

    // Two-step lookahead with chain planning.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 980.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 360.0 * (1.0 - gap / cap);
            if next > 0.5 * cap && fitting_bins_count <= 2 {
                score -= 150.0 * (next / cap);
            }
            if pr >= 2.0 * next && pr < cap {
                score -= 55.0 * (1.0 - pr / cap);
            }
            if pr >= 3.0 * next {
                score -= 35.0 * (next / cap);
            }
            if pr - next >= item_f {
                score -= 42.0 * item_ratio;
            }
            if pr >= next + item_f {
                score -= 22.0 * (1.0 - ((pr - next - item_f) / cap).min(1.0));
            }
            if next > 0 && (post_residual % next_item_size) == 0 && pr < cap {
                score -= 30.0 * (pr / next).min(4.0);
            }
            // Exact two-step drain: next + item == post_residual.
            if (pr - next - item_f).abs() < 1.0 && pr >= next + item_f {
                score -= 85.0;
            }
            let rem = pr - next;
            if rem >= item_f && rem < item_f * 2.5 {
                score -= 18.0 * (1.0 - rem / (2.5 * item_f).max(1.0));
            }
        } else {
            let dead = pr;
            score += 0.65 * dead;
            if dead > 0.0 && dead < next {
                let q = dead / next;
                score += 100.0 * q * (1.0 - q) + 65.0 * (1.0 - q);
                score += 45.0 * q * (next / cap);
            }
        }
        if bin_residual == bin_capacity && next_item_size == item_size {
            score -= 40.0;
        }
    }

    // Quartic dead-space penalty in the awkward zone.
    if pr > 0.0 && pr < 0.25 * cap {
        let r = pr / cap;
        score += 145.0 * r * (1.0 - 4.0 * r) * (1.0 - r) + 25.0 * r * r;
    }

