pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins partitioned into capacity fractions.
    // Class 0: perfectly full. Class 1: tiny dead space. Class 2: half-class, etc.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post_class = post_residual / eighth; // 0..=12 classes
    match post_class {
        0 => score -= 40.0,                    // exact / near-exact fill
        1 => score -= 25.0,                    // <=12 dead space: excellent
        2 => score -= 15.0,                    // <=25 dead space: good
        3 => score -= 6.0,                     // <=37: moderate
        4 => { score += 4.0; }                 // ~half empty: mediocre
        5 | 6 => { score += 10.0; }            // 50-75 dead: poor
        _ => { score += 18.0; }                // mostly empty: wasteful
    }

    // Modulo-10 harmonic ladder: residuals divisible by 10 align with item granularity.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            let chain_class = (post_residual - next_item_size) / eighth;
            score -= match chain_class {
                0 => 30.0,
                1 => 18.0,
                2 => 10.0,
                _ => 3.0,
            };
        } else {
            // next item cannot use this residual: slight penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    } else {
        // Last item: only exactness matters
        score = post_residual as f64 * 2.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is very poor
    // and stream is early enough to amortize it.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = post_residual as f64; // = cap - item for new bin
        let poor_fit_elsewhere = (bin_residual - item_size) as f64;
        score = waste + 55.0 - 30.0 * (1.0 - progress);
        if poor_fit_elsewhere > 60.0 {
            score -= 25.0; // existing fit is bad, new bin more attractive
        }
        if next_item_size > 0 && next_item_size >= post_residual {
            score += 20.0; // fresh bin won't help chain if next is large anyway
        }
    }

    // Crowd coupling: with many open bins, prefer tightening existing ones.
    if open_bins_count > 3 {
        score += (mean_residual - post_residual as f64) * 0.1;
    }

    score
}

