        }
        // Opening a bin for a big item with a small follow-up is fine;
        // opening one for a tiny item late is not.
        if item_ratio < 0.15 && progress > 0.6 && open_bins_count > 2 {
            score += 70.0 * (1.0 - item_ratio * 6.0);
        }
        // NEW: fresh-bin residual (cap - item) should be reusable by the next
        // item; if it would be dead space, penalize opening at all.
        if next_item_size > 0 {
            let fresh_left = cap - item_f;
            if fresh_left > 0.0 && fresh_left < next_item_size as f64 {
                score += 55.0 * (1.0 - fresh_left / (next_item_size as f64));
