            let rem = pr - next;
            if rem >= item_f && rem < item_f * 2.5 {
                score -= 18.0 * (1.0 - rem / (2.5 * item_f).max(1.0));
            }
            // NEW: chain depth — residual after next item still fits the item
            // again, suggesting a multi-item drain; reward proportionally.
            if pr >= 2.0 * (next + item_f) && pr < cap {
                score -= 25.0 * ((pr / (next + item_f)).min(3.0));
            }
        } else {
            let dead = pr;
            score += 0.65 * dead;
            if dead > 0.0 && dead < next {
                let q = dead / next;
                score += 100.0 * q * (1.0 - q) + 65.0 * (1.0 - q);
                score += 45.0 * q * (next / cap);
            }
            // NEW: dead space that equals a fraction of the next item is worse
            // when the stream is long (more chances it stays stranded).
            if dead > 0.0 && dead < next && progress < 0.5 {
                score += 30.0 * (1.0 - dead / next);
            }
        }
        if bin_residual == bin_capacity && next_item_size == item_size {
            score -= 40.0;
        }
