    if next_item_size > 0 && pr > 0.0 && open_bins_count <= 3 {
        let next = next_item_size as f64;
        if (pr + next - cap).abs() < 1.0 {
            score -= 70.0 * (1.0 - progress);
        }
    }

    // NEW: residual utilization gradient — among bins that both fit the item,
    // prefer the one whose post-residual is closest to (but not below) the
    // mean residual band, reducing stranded mid-range gaps.
    if pr > 0.0 && pr < cap && fitting_bins_count > 1 {
        let band = (pr - mean_residual).abs();
        score += 6.0 * (band / cap).min(1.0);
    }

    // NEW: late-stream exact-closure amplification — closing bins in the end
    // phase prevents accumulating many half-empty bins that can never merge.
    if post_residual == 0 && progress > 0.75 {
        score -= 90.0 * progress;
    }

    // NEW: large-item urgency — when the next item is big and few bins can
    // hold it, protect residuals that can still accommodate it.
    if next_item_size > 0 && fitting_bins_count <= 2 && pr >= next_item_size as f64 {
        score -= 20.0 * (next_item_size as f64 / cap);
    }

    // Slight preference for placing small items cheaply.
    score -= 0.05 * item_f;

    score
}

